/* ══ Luma, take seven ═════════════════════════════════════════════════════════
   One vocabulary; every app arranges it around its own purpose.

   The vocabulary is small on purpose, and nothing outside it exists:
     Surfaces  window · side (a half-step darker) · raised (the one selection
               surface) · float (glass, for the few things that hover) · paper
     Controls  icon button · text button · primary (monochrome) · segmented ·
               search field. All soft squares; circles only for round things.
     Floaters  the floating bar · the side panel · popovers. Same material.
   Colour belongs to content. The chrome stays neutral; the accent is sampled
   from the wallpaper and appears only as a hint (a selected icon, a folder, a
   progress line). Tide is the one room lit by its content, because an album's
   colour is what an album is.                                               */

:root { --font: Figtree, system-ui, sans-serif; --read: Newsreader, Georgia, serif; --ease: cubic-bezier(.3, .7, .2, 1); --spring: cubic-bezier(.3, 1.3, .5, 1); --acc: 250; --ah: 95; }
[data-mode="dark"], [data-mode="dark"] .win, [data-mat="frost"][data-mode="light"] .win, [data-mat="frost"][data-mode="light"] .win .isle :is(.fbar, .flo, .pop, .crpop) {
  --wall: url("/wallpapers/prism.png");
  --win: oklch(0.208 0.006 265); --side: oklch(0.182 0.006 265); --raised: oklch(0.285 0.008 265); --float: oklch(0.27 0.008 265 / .78); --float-solid: oklch(0.265 0.008 265);
  --ink: oklch(0.965 0.003 265); --ink-2: oklch(0.82 0.005 265); --ink-3: oklch(0.65 0.006 265); --ink-4: oklch(0.5 0.006 265);
  --fill-1: oklch(1 0 0 / .06); --fill-2: oklch(1 0 0 / .1); --fill-3: oklch(1 0 0 / .16); --hair: oklch(1 0 0 / .075);
  --acc-ink: oklch(0.82 0.09 var(--acc)); --acc-soft: oklch(0.75 0.09 var(--acc) / .16); --folder: oklch(0.74 0.07 var(--acc)); --folder-2: oklch(0.6 0.07 var(--acc));
  --primary: oklch(0.965 0.003 265); --primary-ink: oklch(0.2 0.006 265);
  --sh-win: 0 0 0 1px rgba(0,0,0,.85), 0 2px 4px rgba(0,0,0,.3), 0 18px 40px -12px rgba(0,0,0,.6), 0 40px 90px -24px rgba(0,0,0,.8);
  --rim: inset 0 1px 0 oklch(1 0 0 / .2), inset 0 0 0 1px oklch(1 0 0 / .075);
  --sh-float: 0 0 0 .5px oklch(1 0 0 / .1), 0 12px 32px -8px rgba(0,0,0,.6), 0 2px 6px rgba(0,0,0,.25);
  --hi: oklch(1 0 0 / .07); --good: oklch(0.76 0.15 150); --love: oklch(0.68 0.19 15); --fav: oklch(0.82 0.15 80);
  --wash: oklch(0.42 0.09 var(--ah) / .8); --tint: oklch(0.8 0.1 var(--ah)); --tint-soft: oklch(0.72 0.1 var(--ah) / .18); --pl: oklch(0.32 0.06 var(--ah));
}
[data-mode="light"], [data-mode="light"] .win, [data-mat="frost"][data-mode="light"] .win .isle {
  --wall: url("/wallpapers/meadow.png");
  --win: oklch(0.99 0.002 265); --side: oklch(0.962 0.004 265); --raised: #fff; --float: oklch(0.99 0.002 265 / .8); --float-solid: #fff;
  --ink: oklch(0.2 0.008 265); --ink-2: oklch(0.38 0.008 265); --ink-3: oklch(0.54 0.008 265); --ink-4: oklch(0.68 0.006 265);
  --fill-1: oklch(0.2 0.01 265 / .05); --fill-2: oklch(0.2 0.01 265 / .085); --fill-3: oklch(0.2 0.01 265 / .13); --hair: oklch(0.2 0.01 265 / .09);
  --acc-ink: oklch(0.48 0.12 var(--acc)); --acc-soft: oklch(0.6 0.12 var(--acc) / .14); --folder: oklch(0.8 0.08 var(--acc)); --folder-2: oklch(0.68 0.08 var(--acc));
  --primary: oklch(0.2 0.008 265); --primary-ink: #fff;
  --sh-win: 0 0 0 1px rgba(0,0,0,.14), 0 2px 4px rgba(0,0,0,.06), 0 18px 40px -14px rgba(0,0,0,.22), 0 40px 90px -26px rgba(0,0,0,.4);
  --rim: inset 0 1px 0 rgba(255,255,255,.95), inset 0 0 0 1px rgba(255,255,255,.4);
  --sh-float: 0 0 0 .5px rgba(0,0,0,.1), 0 12px 32px -8px rgba(0,0,0,.2), 0 2px 6px rgba(0,0,0,.06);
  --hi: rgba(255,255,255,.8); --good: oklch(0.62 0.15 150); --love: oklch(0.6 0.2 15); --fav: oklch(0.72 0.16 75);
  --wash: oklch(0.87 0.07 var(--ah) / .9); --tint: oklch(0.5 0.12 var(--ah)); --tint-soft: oklch(0.6 0.12 var(--ah) / .14); --pl: oklch(0.93 0.035 var(--ah));
}
.raised-row { background: var(--raised); box-shadow: inset 0 1px 0 var(--hi), 0 1px 2px rgba(0,0,0,.12); }
* { box-sizing: border-box; }
@supports (corner-shape: superellipse(1.6)) { * { corner-shape: superellipse(1.6); } .round, .round * { corner-shape: round; } }
html, body { margin: 0; height: 100%; overflow: hidden; }
body { background: #111; font: 13px/1.45 var(--font); font-kerning: normal; text-rendering: optimizeLegibility; font-optical-sizing: auto; color: var(--ink); -webkit-font-smoothing: antialiased; letter-spacing: -.006em; }
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
img { display: block; }
svg.i { display: block; flex: none; width: 18px; height: 18px; }
.num { font-variant-numeric: tabular-nums; }
:focus-visible { outline: 2px solid var(--acc-ink); outline-offset: 2px; }

/* Review bar, not part of the design. */
.review { position: fixed; inset: 0 0 auto 0; height: 40px; z-index: 1000; display: flex; align-items: center; gap: 12px; padding: 0 14px; background: #141414; color: #e8e8e8; font-size: 12.5px; border-bottom: 1px solid #242424; }
.review strong { font-weight: 600; } .review small { color: #8a8a8a; } .review .sp { flex: 1; }
.rseg { display: flex; gap: 2px; padding: 3px; border-radius: 9px; background: #232323; }
.rseg button, .rbtn { height: 26px; padding: 0 12px; border-radius: 7px; color: #bdbdbd; font-weight: 500; }
.rbtn { height: 30px; background: #232323; color: #ddd; border-radius: 8px; }
.rseg button.on, .rbtn.on { background: #f2f2f2; color: #111; }

/* Desk and shelf. */
.desk { position: fixed; inset: 40px 0 0 0; overflow: hidden; background: #222; }
/* The wallpaper is blurred hard, as in the Design Center: colour and light, not a picture competing with the windows. */
.desk { background-position: center; background-size: cover; background-repeat: no-repeat; } /* blurred once in JS, never live */
.desk.phoning::after { content: ""; position: absolute; inset: 0; background: rgba(0,0,0,.5); z-index: 99998; pointer-events: none; }
.shelf { position: absolute; inset: auto 0 0 0; height: 58px; z-index: 100000; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; padding: 0 10px;
  background: oklch(0.19 0.01 265 / .72); color: oklch(0.96 0 0); backdrop-filter: blur(30px) saturate(1.8); -webkit-backdrop-filter: blur(30px) saturate(1.8); box-shadow: inset 0 .5px 0 oklch(1 0 0 / .1); }
[data-mode="light"] .shelf { background: oklch(0.97 0.004 265 / .74); color: oklch(0.2 0.01 265); box-shadow: inset 0 .5px 0 rgba(0,0,0,.08); }
.shelf .l, .shelf .r { display: flex; align-items: center; gap: 6px; } .shelf .r { justify-content: flex-end; }
.sb { height: 40px; min-width: 40px; padding: 0 11px; border-radius: 11px; display: flex; align-items: center; gap: 10px; opacity: .88; } .sb:hover { background: oklch(0.5 0 0 / .14); opacity: 1; }
.sb.q { width: 230px; background: oklch(0.5 0 0 / .12); } .sb.q span { opacity: .6; } .sb.q kbd { margin-left: auto; font: 500 11px var(--font); opacity: .5; letter-spacing: .01em; }
.apps { display: flex; gap: 2px; }
.dk { position: relative; width: 50px; height: 46px; border-radius: 12px; display: grid; place-items: center; } .dk:hover { background: oklch(0.5 0 0 / .14); }
.dk img { width: 33px; height: 33px; border-radius: 9px; transition: transform .2s var(--spring); } .dk:active img { transform: scale(.9); }
.dk .run { position: absolute; left: 50%; bottom: 3px; width: 4px; height: 4px; margin-left: -2px; border-radius: 2px; background: currentColor; opacity: 0; transition: width .25s var(--ease), margin .25s var(--ease), opacity .2s; }
.dk.running .run { opacity: .45; } .dk.front .run { opacity: 1; width: 16px; margin-left: -8px; }
.clock { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.15; } .clock b { font-weight: 600; font-size: 12.5px; } .clock span { font-size: 11px; opacity: .6; letter-spacing: .01em; }

/* ══ Vocabulary ════════════════════════════════════════════════════════════ */
.win { position: absolute; display: flex; min-width: 380px; min-height: 420px; background: var(--win); color: var(--ink); border-radius: 20px; overflow: hidden;
  box-shadow: var(--sh-win), var(--rim); container: win / inline-size; transition: opacity .22s ease, transform .3s var(--ease); }
.win.min { opacity: 0; transform: translateY(40%) scale(.2); pointer-events: none; }
/* Every desktop window's outer edge (25 Oct 2026): a faint 1px outline drawn just inside the frame, on top of its own rim and shadow.
   Phone and tablet frames (.phone) run edge to edge and have none. */
.win:not(.phone) { outline: 1px solid rgba(255,255,255,.08); outline-offset: -1px; }
.win[hidden] { display: none; } .win.drag { transition: none; will-change: transform; }
.win.phone { border-radius: 42px; z-index: 99999 !important; box-shadow: 0 0 0 10px #0c0c0d, 0 0 0 11px #2a2a2c, 0 40px 90px rgba(0,0,0,.6); }
.win.phone .wctl { display: none; }
.grip { position: absolute; right: 0; bottom: 0; width: 18px; height: 18px; cursor: nwse-resize; z-index: 40; }
[data-drag] { cursor: default; user-select: none; }
.wctl { position: absolute; top: 12px; right: 12px; z-index: 30; display: flex; gap: 2px; }
.wctl button { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; color: var(--ink-3); transition: background .12s, color .12s; }
.wctl button:hover { background: var(--fill-2); color: var(--ink); } .wctl button[data-w="close"]:hover { background: oklch(0.6 0.2 25); color: #fff; }
.wctl svg.i { width: 14px; height: 14px; }
.main { position: relative; flex: 1; min-width: 0; display: flex; flex-direction: column; }
.scroll { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--fill-3) transparent; }

.ib { position: relative; width: 36px; height: 36px; flex: none; border-radius: 10px; display: grid; place-items: center; color: var(--ink-2); transition: background .12s, color .12s; }
.ib:hover { background: var(--fill-1); color: var(--ink); } .ib.on { background: var(--fill-2); color: var(--ink); } .ib[disabled] { opacity: .3; pointer-events: none; }
.ib.loved { color: var(--love); } .ib.loved svg.i { fill: currentColor; }
.bt { height: 36px; padding: 0 12px; border-radius: 10px; display: inline-flex; align-items: center; gap: 7px; font-weight: 500; white-space: nowrap; color: var(--ink); transition: background .12s, filter .12s; }
.bt:hover { background: var(--fill-1); } .bt svg.i { width: 16px; height: 16px; }
.bt.fill { background: var(--fill-1); } .bt.fill:hover { background: var(--fill-2); }
.bt.pri { background: var(--primary); color: var(--primary-ink); padding: 0 14px; } .bt.pri:hover { filter: brightness(1.12); }
.bt.sm { height: 28px; padding: 0 9px; border-radius: 8px; font-size: 12px; letter-spacing: .01em; }
.badge { position: absolute; top: 3px; right: 2px; min-width: 15px; height: 15px; padding: 0 4px; border-radius: 5px; background: var(--primary); color: var(--primary-ink); font-size: 9.5px; font-weight: 700; display: grid; place-items: center; letter-spacing: .01em; }
.srch { height: 36px; width: 220px; flex: none; display: flex; align-items: center; gap: 8px; padding: 0 11px; border-radius: 10px; background: var(--fill-1); color: var(--ink-3); transition: background .15s, box-shadow .15s; }
.srch:hover { background: var(--fill-2); } .srch:focus-within { box-shadow: 0 0 0 1.5px var(--acc-ink); color: var(--ink); }
.srch svg.i { width: 16px; height: 16px; } .srch input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--ink); font: 13px var(--font); } .srch input::placeholder { color: var(--ink-3); }
.seg { position: relative; display: flex; height: 36px; padding: 3px; border-radius: 10px; background: var(--fill-1); flex: none; }
.seg .ind { position: absolute; top: 3px; bottom: 3px; border-radius: 7px; background: var(--raised); box-shadow: inset 0 1px 0 var(--hi), 0 1px 3px rgba(0,0,0,.2); transition: left .28s var(--ease), width .28s var(--ease); }
.seg button { position: relative; z-index: 1; height: 30px; min-width: 30px; padding: 0 12px; border-radius: 7px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; color: var(--ink-3); font-weight: 500; }
.seg button:hover, .seg button.on { color: var(--ink); } .seg button svg.i { width: 16px; height: 16px; } .seg.ico button { padding: 0 8px; }
.vr { width: 1px; height: 20px; background: var(--hair); margin: 0 4px; flex: none; }
.stat { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--good); flex: none; corner-shape: round;
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--good) 22%, transparent), 0 0 10px color-mix(in oklch, var(--good) 70%, transparent); }
.avs { display: flex; } .avs i { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font: 600 10px var(--font); color: #fff; font-style: normal; box-shadow: 0 0 0 2px var(--win); margin-left: -3px; corner-shape: round; letter-spacing: .01em; } .avs i:first-child { margin-left: 0; }

/* The title: where you are, and a sentence about it. */
.ttl { padding: 22px 130px 12px 28px; }
.ttl h1 { margin: 0; font-size: 24px; font-weight: 650; letter-spacing: -.024em; line-height: 1.15; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.meta { display: flex; align-items: center; gap: 0 7px; margin-top: 4px; color: var(--ink-3); font-size: 12.5px; white-space: nowrap; overflow: hidden; }
.meta i.d { width: 2.5px; height: 2.5px; border-radius: 50%; background: var(--ink-4); flex: none; corner-shape: round; }
.meta button:hover { color: var(--ink); }

/* The rail: a slim column of places, the app's mark at the top. */
.rail { width: 88px; flex: none; display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 16px 0 14px; background: var(--side); }
.rail .mark { width: 36px; height: 36px; border-radius: 9px; margin-bottom: 16px; box-shadow: 0 1px 3px rgba(0,0,0,.3); }
.ri { width: 76px; display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 8px 0 7px; border-radius: 12px; transition: background .18s; font-size: 11.5px; font-weight: 550; letter-spacing: .01em; color: var(--ink-2); text-align: center; }
.ri .ico { width: 32px; height: 24px; display: grid; place-items: center; }
.ri svg.i { width: 19px; height: 19px; }
.ri:hover { background: var(--fill-1); } .ri:hover { color: var(--ink-2); }
.ri.on { color: var(--ink); } .ri.on { background: var(--raised); box-shadow: inset 0 1px 0 var(--hi), 0 1px 2px rgba(0,0,0,.15); } .ri.on svg.i { color: var(--acc-ink); }
.ri .lab { max-width: 70px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ri .cap { width: 30px; height: 3px; border-radius: 2px; background: var(--fill-2); margin-top: 1px; overflow: hidden; } .ri .cap i { display: block; height: 100%; background: var(--ink-3); }
.rail .rsep { width: 26px; height: 1px; background: var(--hair); margin: 8px 0; }
.rail .foot { margin-top: auto; display: grid; place-items: center; width: 40px; height: 32px; border-radius: 10px; } .rail .foot:hover { background: var(--fill-1); }

/* The floating bar: the one thing that hovers, holding what this screen is for. */
.fbar { position: absolute; left: 50%; bottom: 16px; z-index: 20; display: flex; align-items: center; gap: 2px; padding: 5px; border-radius: 16px; max-width: calc(100% - 24px); white-space: nowrap;
  transform: translateX(-50%); background: var(--float); backdrop-filter: blur(24px) saturate(1.7); -webkit-backdrop-filter: blur(24px) saturate(1.7); box-shadow: var(--sh-float), inset 0 1px 0 var(--hi); }
.fbar.morph > * { animation: morph .26s var(--ease) both; }
@keyframes morph { from { opacity: 0; transform: translateY(4px); } }
.fbar .who { display: flex; align-items: center; gap: 10px; padding: 0 10px 0 4px; min-width: 0; }
.fbar .who .th { width: 28px; height: 28px; border-radius: 7px; object-fit: cover; flex: none; background: var(--fill-2); display: grid; place-items: center; }
.fbar .who .th svg.i { width: 16px; height: 16px; color: var(--ink-2); }
.fbar .who b { font-weight: 500; overflow: hidden; text-overflow: ellipsis; max-width: 220px; } .fbar .who span { color: var(--ink-3); }
.fbar .count { min-width: 64px; text-align: center; color: var(--ink-2); font-weight: 500; font-variant-numeric: tabular-nums; }
/* The side panel and popovers: same glass. */
.panel { position: absolute; right: 12px; top: 64px; bottom: 80px; width: 288px; z-index: 18; display: flex; flex-direction: column; border-radius: 16px; overflow: hidden;
  background: var(--float); backdrop-filter: blur(24px) saturate(1.7); -webkit-backdrop-filter: blur(24px) saturate(1.7); box-shadow: var(--sh-float), inset 0 1px 0 var(--hi); animation: panelin .26s var(--ease); }
@keyframes panelin { from { opacity: 0; transform: translateX(10px); } }
.panel .ph { display: flex; align-items: center; gap: 4px; padding: 10px 8px 4px 16px; } .panel .ph b { flex: 1; font-weight: 600; font-size: 13.5px; } .panel .ph .ib { width: 30px; height: 30px; }
.panel .pb { flex: 1; overflow-y: auto; padding: 6px 16px 16px; scrollbar-width: none; }
.pop { position: absolute; z-index: 60; min-width: 220px; padding: 5px; border-radius: 14px; background: var(--float-solid); box-shadow: var(--sh-float), inset 0 1px 0 var(--hi); animation: morph .16s var(--ease); }
.pop h6 { margin: 7px 10px 5px; font-size: 11.5px; font-weight: 600; color: var(--ink-3); letter-spacing: .01em; }
.mi { width: 100%; min-height: 36px; display: flex; align-items: center; gap: 11px; padding: 6px 10px; border-radius: 9px; text-align: left; } .mi:hover { background: var(--fill-1); }
.mi svg.i { width: 16px; height: 16px; color: var(--ink-3); } .mi b { display: block; font-weight: 500; } .mi .sub { display: block; font-size: 11.5px; color: var(--ink-3); letter-spacing: .01em; }
.mi .end { margin-left: auto; color: var(--ink-2); } .mi .dot { margin-left: auto; width: 8px; height: 8px; border-radius: 50%; corner-shape: round; }
.facts { margin: 12px 0 0; } .facts div { display: flex; justify-content: space-between; gap: 12px; padding: 8px 0; font-size: 12.5px; box-shadow: inset 0 -.5px 0 var(--hair); }
.facts dt { color: var(--ink-3); } .facts dd { margin: 0; font-weight: 500; text-align: right; }
.chip { height: 26px; padding: 0 10px 0 9px; border-radius: 8px; display: inline-flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 500; background: var(--fill-1); letter-spacing: .01em; }
.chip i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); corner-shape: round; }
/* Rows in a wider sidebar (Tide, Viola) select with the same raised surface as the rail. */
.si { width: 100%; height: 34px; display: flex; align-items: center; gap: 11px; padding: 0 10px; border-radius: 10px; color: var(--ink-2); font-weight: 500; text-align: left; }
.si svg.i { width: 17px; height: 17px; color: var(--ink-3); } .si .lab { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.si:hover { background: var(--fill-1); } .si.on { color: var(--ink); background: var(--raised); box-shadow: inset 0 1px 0 var(--hi), 0 1px 2px rgba(0,0,0,.15); } .si.on svg.i { color: var(--acc-ink); }
.sh { display: flex; align-items: center; margin: 18px 10px 6px; font-size: 11.5px; font-weight: 600; color: var(--ink-3); letter-spacing: .01em; } .sh .ib { width: 24px; height: 24px; margin-left: auto; } .sh .ib svg.i { width: 14px; height: 14px; }
.navbtn { display: none !important; }

/* ══ Photos: the photographs are the interface ═════════════════════════════ */
.pbody { padding: 0 24px 96px; }
.day { display: flex; align-items: baseline; gap: 10px; padding: 18px 2px 10px; } .day:first-child { padding-top: 6px; }
.day b { font-size: 16px; font-weight: 650; letter-spacing: -.018em; } .day span { color: var(--ink-3); }
.pgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)); gap: 3px; border-radius: 12px; overflow: hidden; }
.pgrid.big { grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); }
.pc { position: relative; aspect-ratio: 1; margin: 0; overflow: hidden; background: var(--fill-1); cursor: zoom-in; }
.pc img { width: 100%; height: 100%; object-fit: cover; transition: transform .6s var(--ease), filter .3s; } .pc:hover img { transform: scale(1.035); }
.pc .fav { position: absolute; left: 8px; bottom: 8px; } .pc .fav svg.i { width: 15px; height: 15px; color: #fff; fill: #fff; filter: drop-shadow(0 1px 2px rgba(0,0,0,.5)); }
.years { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 10px; }
.year { position: relative; aspect-ratio: 16 / 10; border-radius: 12px; overflow: hidden; text-align: left; } .year img { width: 100%; height: 100%; object-fit: cover; transition: transform .6s var(--ease); } .year:hover img { transform: scale(1.03); }
.year::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 45%, rgba(0,0,0,.6)); }
.year b { position: absolute; left: 18px; bottom: 14px; z-index: 1; color: #fff; font-size: 32px; font-weight: 700; letter-spacing: -.035em; } .year span { position: absolute; right: 16px; bottom: 19px; z-index: 1; color: rgba(255,255,255,.82); font-weight: 500; font-size: 12.5px; }
.viewer { position: absolute; inset: 0; z-index: 12; display: grid; grid-template: minmax(0, 1fr) / minmax(0, 1fr); place-items: center; padding: 64px 28px 88px; background: #0c0c0d; color: #f3f3f2; animation: morph .24s var(--ease); }
