.win.viewing .wctl button { color: rgba(255,255,255,.6); }
.win.viewing .fbar { --ink: #f3f3f2; --ink-2: rgba(255,255,255,.8); --ink-3: rgba(255,255,255,.55); --fill-1: rgba(255,255,255,.08); --fill-2: rgba(255,255,255,.14); --hair: rgba(255,255,255,.1); --float: rgba(40,40,44,.72); --primary: #f3f3f2; --primary-ink: #111; }
.ib.faved { color: var(--love); } .ib.faved svg.i { fill: currentColor; }

/* ══ Floating island (Photos, takes nine and ten) ══════════════════════════
   A slim title bar and the sidebar sit on the frame; the content is one island.
   .lightframe: the frame is the lighter plane, the island sits darker (v9).
   .darkframe: the frame is the darker plane, the island sits lighter (v10). */
.iwin { flex-direction: column; }
.tbar { height: 46px; flex: none; display: flex; align-items: center; gap: 9px; padding: 0 130px 0 14px; }
.tbar img { width: 22px; height: 22px; border-radius: 6px; box-shadow: 0 1px 2px rgba(0,0,0,.3); }
.tbar b { font-weight: 600; font-size: 13.5px; letter-spacing: -.01em; } .tbar .chev svg.i { width: 14px; height: 14px; color: var(--ink-3); }
.iwin .wctl { top: 8px; right: 10px; }
.ibody { flex: 1; min-height: 0; display: flex; }
.pside { width: 212px; flex: none; display: flex; flex-direction: column; padding: 0 10px 10px; }
.pside .scr { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; } .pside .sh:first-child { margin-top: 4px; }
.pside .si em { font-style: normal; font-size: 11.5px; color: var(--ink-4); letter-spacing: .01em; }
/* The island reads as set into the frame: a light lip outside, a crisp dark edge inside, and a soft
   shadow falling in from the top. The inner layer sits above the content so scrolling photos never cover it. */
.isle { margin: 0 8px 8px 0; border-radius: 12px; overflow: hidden; background: var(--isle); box-shadow: var(--isle-out); }
.isle::after { content: ""; position: absolute; inset: 0; z-index: 30; border-radius: inherit; pointer-events: none; box-shadow: var(--isle-in); }
@supports (corner-shape: superellipse(1.6)) { .isle::after { corner-shape: superellipse(1.6); } }
[data-mode="dark"] .iwin, [data-mode="dark"] #w-filer { --isle-out: 0 0 0 1px oklch(1 0 0 / .06);
  --isle-in: inset 0 0 0 1px rgba(0,0,0,.5), inset 0 1px 0 1px rgba(0,0,0,.18), inset 0 3px 8px -2px rgba(0,0,0,.45), inset 0 -1px 0 oklch(1 0 0 / .03); }
[data-mode="light"] .iwin, [data-mode="light"] #w-filer { --isle-out: 0 0 0 1px rgba(255,255,255,.8);
  --isle-in: inset 0 0 0 1px rgba(0,0,0,.09), inset 0 1px 0 1px rgba(0,0,0,.035), inset 0 3px 8px -3px rgba(0,0,0,.14); }
.iwin .ttl { padding: 20px 24px 10px; } .iwin .pbody { padding: 0 20px 96px; }
[data-mode="dark"] .win.lightframe { --win: oklch(0.305 0.006 265); --isle: oklch(0.212 0.006 265); --raised: oklch(0.375 0.008 265); --fill-1: oklch(1 0 0 / .07); }
[data-mode="dark"] .win.darkframe { --win: oklch(0.195 0.006 265); --isle: oklch(0.262 0.006 265); --raised: oklch(0.33 0.008 265); }
[data-mode="light"] .win.lightframe { --win: oklch(0.995 0.001 265); --isle: oklch(0.955 0.004 265); }
[data-mode="light"] .win.lightframe .pside .si.on { background: var(--fill-2); box-shadow: none; }
[data-mode="light"] .win.darkframe { --win: oklch(0.942 0.005 265); --isle: #fff; }
@container win (max-width: 720px) { .pside { display: none; } .win.navopen .pside { display: flex; position: absolute; z-index: 35; left: 8px; top: 50px; bottom: 8px; width: 240px; padding-top: 10px; border-radius: 14px; background: var(--float-solid); box-shadow: var(--sh-float); } .isle { margin-left: 8px; } .tbar { padding-right: 14px; } }

/* ══ The kit: recessed, raised, floating ════════════════════════════════════
   Three depths, and every control is one of them:
     Recessed  where things go: the island, a text field, the track tabs ride in.
               Island colour, a dark inner edge, a soft shadow falling in from the top.
     Raised    what you have chosen or can press: the selected tab, the selected
               place in the sidebar, buttons. A lit top edge and a small shadow below.
     Floating  what hovers: the action bar, popovers. The frame's own material with
               the window's rim, so it reads as a piece of the frame lifted up.
   Inside a bar, radii are concentric: bar 16, padding 4, control 12, chip 9.       */
[data-mode="dark"] .win, [data-mat="frost"][data-mode="light"] .win, [data-mat="frost"][data-mode="light"] .win .isle :is(.fbar, .flo, .pop, .crpop) {
  --well: oklch(0.212 0.006 265); --well-edge: inset 0 0 0 1px rgba(0,0,0,.42), inset 0 1px 2px rgba(0,0,0,.35), 0 1px 0 oklch(1 0 0 / .05);
  --chip: oklch(0.405 0.008 265); --chip-edge: inset 0 1px 0 oklch(1 0 0 / .1), 0 0 0 1px rgba(0,0,0,.32), 0 1px 2px rgba(0,0,0,.35);
  --key: linear-gradient(180deg, oklch(0.93 0.003 265), oklch(0.855 0.004 265)); --key-ink: oklch(0.2 0.006 265);
  --key-edge: inset 0 1px 0 rgba(255,255,255,.75), 0 0 0 1px rgba(0,0,0,.45), 0 1px 3px rgba(0,0,0,.4);
  --bar: oklch(0.305 0.006 265 / .88); --bar-edge: inset 0 1px 0 oklch(1 0 0 / .11), 0 0 0 1px rgba(0,0,0,.55), 0 12px 32px -8px rgba(0,0,0,.6), 0 2px 6px rgba(0,0,0,.3); }
[data-mode="light"] .win, [data-mat="frost"][data-mode="light"] .win .isle {
  --well: oklch(0.955 0.004 265); --well-edge: inset 0 0 0 1px rgba(0,0,0,.075), inset 0 1px 2px rgba(0,0,0,.06), 0 1px 0 rgba(255,255,255,.9);
  --chip: #fff; --chip-edge: inset 0 1px 0 #fff, 0 0 0 1px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.12);
  --key: linear-gradient(180deg, oklch(0.33 0.008 265), oklch(0.22 0.008 265)); --key-ink: #fff;
  --key-edge: inset 0 1px 0 rgba(255,255,255,.16), 0 0 0 1px rgba(0,0,0,.7), 0 1px 3px rgba(0,0,0,.25);
  --bar: rgba(255,255,255,.88); --bar-edge: inset 0 1px 0 #fff, 0 0 0 1px rgba(0,0,0,.09), 0 12px 32px -8px rgba(0,0,0,.22), 0 2px 6px rgba(0,0,0,.06); }
/* Floating: the action bar */
.iwin .fbar { gap: 4px; padding: 4px; border-radius: 16px; background: var(--bar); box-shadow: var(--bar-edge); }
.iwin .fbar .vr { display: none; }
.iwin .fbar .ib, .iwin .fbar .bt { border-radius: 12px; }
/* Recessed: fields and tracks */
.iwin .srch { height: 36px; border-radius: 12px; background: var(--well); box-shadow: var(--well-edge); color: var(--ink-3); }
.iwin .srch:hover { background: var(--well); color: var(--ink-2); }
.iwin .srch:focus-within { box-shadow: var(--well-edge), 0 0 0 2px var(--acc-ink); }
.iwin .seg { height: 36px; padding: 3px; border-radius: 12px; background: var(--well); box-shadow: var(--well-edge); }
.iwin .seg button { height: 30px; border-radius: 9px; padding: 0 13px; font-weight: 500; }
/* Raised: what you have chosen, and what you press */
.iwin .seg .ind { border-radius: 9px; background: var(--chip); box-shadow: var(--chip-edge); }
.iwin .ri.on, .iwin .si.on { background: var(--chip); box-shadow: var(--chip-edge); }
.iwin .bt.pri { height: 36px; padding: 0 15px 0 13px; border-radius: 12px; background: var(--key); color: var(--key-ink); box-shadow: var(--key-edge); font-weight: 600; letter-spacing: -.01em; transition: filter .12s, transform .12s; }
.iwin .bt.pri:hover { filter: brightness(1.04); } .iwin .bt.pri:active { transform: translateY(.5px); filter: brightness(.96); }
.iwin .bt.pri svg.i { width: 16px; height: 16px; }
.iwin.viewing .fbar { --bar: rgba(38,38,42,.78); --bar-edge: inset 0 1px 0 rgba(255,255,255,.08), 0 0 0 1px rgba(0,0,0,.6), 0 12px 32px -8px rgba(0,0,0,.6);
  --chip: rgba(255,255,255,.16); --key: linear-gradient(180deg, #f4f4f5, #dcdcdf); --key-ink: #16161a; }

/* ══ Viola in the kit ═══════════════════════════════════════════════════════ */
[data-mode="dark"] .iwin, [data-mat="frost"][data-mode="light"] .iwin, [data-mat="frost"][data-mode="light"] .iwin .isle :is(.fbar, .flo, .pop, .crpop) { --card: oklch(0.35 0.007 265); --pop: oklch(0.315 0.006 265); }
[data-mode="light"] .iwin, [data-mat="frost"][data-mode="light"] .iwin .isle { --card: #fff; --pop: #fff; }
.vtbar { gap: 9px; }
.vtbar .vaddr, .vtbar-x { flex: 0 1 560px; margin: 0 auto; height: 32px; border-radius: 10px; background: var(--well); box-shadow: var(--well-edge); padding: 0 4px 0 10px; }
.vtbar .vaddr:hover { background: var(--well); color: var(--ink); }
.vtbar .vaddr:focus-within { box-shadow: var(--well-edge), 0 0 0 2px var(--acc-ink); }
.vtbar .vaddr .star { width: 26px; height: 26px; border-radius: 8px; }
.vwin .vside { width: 244px; background: transparent; padding: 2px 10px 10px; }
.vwin .wsbtn { width: 100%; height: 36px; margin-bottom: 8px; padding: 0 8px 0 10px; border-radius: 10px; font-weight: 600; text-align: left; }
.vwin .wsbtn span { flex: 1; } .vwin .wsbtn em { font-style: normal; font-weight: 500; font-size: 12px; color: var(--ink-3); letter-spacing: .01em; }
.vwin .pins { gap: 6px; margin-bottom: 10px; } .vwin .pin { height: 40px; border-radius: 10px; background: var(--card); box-shadow: var(--chip-edge); } .vwin .pin:hover { filter: brightness(1.08); }
.iwin .pop { background: var(--pop); color: var(--ink); box-shadow: var(--bar-edge); border-radius: 14px; }
.vwin .dlpop { right: auto; left: 50%; top: auto; bottom: 68px; transform: translateX(-12%); }
.vwin .wspop { left: 10px; top: 92px; width: 234px; }
/* Viola's title bar: the page title centred on the window with its site icon; off centre and cut short only when room runs out (#12) */
#v-top { display: grid; grid-template-columns: minmax(max-content, 1fr) minmax(0, auto) minmax(124px, 1fr); column-gap: 12px; padding: 0 12px 0 14px; }
#v-top .vtl { display: flex; align-items: center; gap: 9px; } #v-top .vttl { margin: 0; max-width: none; min-width: 0; display: flex; align-items: center; gap: 7px; justify-self: center; font-size: 12.5px; color: var(--ink-2); }
#v-top .vttl > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } #v-top .vttl img { width: 14px; height: 14px; flex: none; border-radius: 3px; box-shadow: none; }
/* Sidebar toggle (LumaUI, shared block): what each app's closed sidebar looks like */
.vside, #w-filer .rail, #w-photos .pside { transition: width .28s var(--ease), padding .28s var(--ease), opacity .2s; }
#w-filer.lsideoff .rail, #w-photos.lsideoff .pside { width: 0 !important; min-width: 0; padding-left: 0; padding-right: 0; opacity: 0; overflow: hidden; } #w-filer.lsideoff .ibody, #w-photos.lsideoff .ibody { padding-left: 8px; }
/* Viola closed: a strip of tab icons, so every tab stays one click away */
.vwin.lsideoff .vside { width: 64px; padding: 12px 8px; align-items: center; }
.vwin.lsideoff .vside :is(.pins, .wsbtn, .grph, .tab .lab, .tab .snd, .tab .x, .media, [data-vnew] .lab) { display: none !important; } .vwin.lsideoff .vside :is(.tab, .grp .tab, [data-vnew]) { width: 44px; padding: 0; justify-content: center; }
/* On a phone: the sidebar is a drawer from the left; the bar keeps Back, the address and what matters; Downloads is a bottom drawer */
#w-viola.phone.navopen .vside { display: flex !important; position: absolute; z-index: 35; left: 8px; top: 8px; bottom: 8px; width: 264px; padding: 12px 10px 10px; align-items: stretch; border-radius: 20px; background: var(--pop); box-shadow: var(--sh-float), 0 0 0 100vmax oklch(0 0 0 / .3); }
#w-viola.phone.navopen .vside .pins { display: grid !important; } #w-viola.phone.navopen .vside :is(.wsbtn, .grph) { display: flex !important; } #w-viola.phone.navopen .vside :is(.tab .lab, [data-vnew] .lab) { display: block !important; }
#w-viola.phone.navopen .vside :is(.tab, .grp .tab, [data-vnew]) { width: 100%; padding: 0 10px; justify-content: flex-start; } #w-viola.phone.navopen .vside .media { display: none !important; }
#w-viola.phone #v-nav :is([aria-label="Forward"], [data-vreload]) { display: none; }
#w-viola.phone .dlpop { left: 0 !important; right: 0 !important; top: auto; bottom: 0; width: auto; transform: none; padding: 26px 10px 14px; border-radius: 28px 28px 0 0; box-shadow: 0 0 0 100vmax oklch(0 0 0 / .32), var(--sh-float); }
#w-viola.phone .dlpop::before { content: ""; position: absolute; top: 9px; left: 50%; width: 36px; height: 5px; margin-left: -18px; border-radius: 3px; background: var(--fill-3); }
.vwin [data-vdl] { position: relative; } .vwin [data-vdl] .lcount { position: absolute; top: 1px; right: -2px; height: 16px; min-width: 16px; padding: 0 4px; font-size: 10px; }
.dlls .lfc .lfx + .lopenb, .dlls .lfc .bt.sm + .bt.sm { margin-left: 2px; } .lprog.paused i { opacity: .45; }
.vnav.tuck { pointer-events: none; }
/* Tuck and nub: a floating bar over long content steps aside while you read, and leaves a nub
   behind so you always know something lives there. The bar squashes down into the edge and
   the nub lands with a small gooey bounce; touching the nub stretches it and springs the bar
   back out. Transforms only, so it stays smooth over live content. */
.fbar.tucks { transform-origin: 50% 100%; transition: transform .5s cubic-bezier(.3, 1.35, .45, 1), opacity .12s ease; }
.fbar.tucks > * { transition: opacity .14s ease .08s; }
.fbar.tucks.tuck { transform: translate(-50%, 22px) scale(.16, .14); opacity: 0; transition: transform .36s cubic-bezier(.5, 0, .2, 1), opacity .2s ease .14s; }
.fbar.tucks.tuck > * { opacity: 0; transition-delay: 0s; }
/* The lip: when the bar tucks, the frame itself rises into the island, a small tab of frame
   with concave shoulders, wrapped by the island's own edge and shadow, and a chevron that
   says something lives here. The bar sinks into it; touching it brings the bar back out. */
.vwin .ibody { position: relative; }
.fnub { position: absolute; left: calc(50% + 118px); bottom: 6px; z-index: 31; width: 100px; height: 20px; margin-left: -50px; padding: 0;
  transform-origin: 50% 100%; transform: scaleY(0); opacity: 0; pointer-events: none;
  filter: drop-shadow(0 -1px 3px rgba(0,0,0,.35)); transition: transform .2s cubic-bezier(.5, 0, .8, .4), opacity .08s ease .14s; }
.fnub svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.fnub .fill { fill: var(--win); } .fnub .edge { fill: none; stroke: rgba(0,0,0,.5); stroke-width: 1; } .fnub .lip { fill: none; stroke: oklch(1 0 0 / .09); stroke-width: 1; }
.fnub .chev { position: absolute; left: 50%; top: 4px; width: 12px; height: 12px; margin-left: -6px; line-height: 0; color: var(--ink-3); transition: color .15s, transform .25s var(--spring); }
.fnub .chev svg.i { width: 12px; height: 12px; stroke-width: 2; }
.fnub.on { transform: none; opacity: 1; pointer-events: auto; transition: transform .5s cubic-bezier(.3, 1.35, .5, 1) .14s, opacity .1s ease .14s; }
.fnub.on:hover { transform: scaleY(1.12); } .fnub.on:hover .chev { color: var(--ink); transform: translateY(-1px); }
[data-mode="light"] .fnub { filter: drop-shadow(0 -1px 2px rgba(0,0,0,.08)); } [data-mode="light"] .fnub .edge { stroke: rgba(0,0,0,.1); } [data-mode="light"] .fnub .lip { stroke: #fff; }
@media (prefers-reduced-motion: reduce) { .fbar.tucks, .fbar.tucks.tuck, .fnub { transition: opacity .15s; animation: none !important; } }
.vnav .gap { width: 10px; } .vnav .ib svg.i { width: 18px; height: 18px; }
.vwin .vpage .scroll.start { background: var(--isle); }
.vwin .w-start .q { background: var(--well); box-shadow: var(--well-edge); border-radius: 14px; }
.vwin .w-tile .tb2 { background: var(--card); box-shadow: var(--chip-edge); }
/* The media widget */
.media { display: grid; grid-template-columns: 40px minmax(0, 1fr) 34px; grid-template-rows: auto auto; align-items: center; gap: 10px 10px; margin-top: 8px; padding: 10px; border-radius: 14px; background: var(--card); box-shadow: var(--chip-edge); }
.media img { width: 40px; height: 40px; border-radius: 9px; object-fit: cover; box-shadow: 0 0 0 .5px rgba(0,0,0,.3); }
.media .tx { min-width: 0; line-height: 1.3; cursor: pointer; } .media .tx b { display: block; font-weight: 600; font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.media .tx > span { display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--ink-3); white-space: nowrap; overflow: hidden; letter-spacing: .01em; }
.media.paused .eq i { animation: none; height: 3px; }
.mkey { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--key); color: var(--key-ink); box-shadow: var(--key-edge); corner-shape: round; transition: transform .15s var(--spring); }
.mkey:hover { transform: scale(1.05); } .mkey:active { transform: scale(.95); } .mkey svg.i { width: 14px; height: 14px; fill: currentColor; }
.mtrack { grid-column: 1 / -1; height: 4px; border-radius: 2px; background: var(--well); box-shadow: inset 0 0 0 .5px rgba(0,0,0,.35); overflow: hidden; margin-top: 2px; }
.mtrack i { display: block; height: 100%; border-radius: 2px; background: var(--acc-ink); }
.media .mt { grid-row: 3; font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; margin-top: -4px; letter-spacing: .01em; } .media .mt.l { grid-column: 1 / 3; } .media .mt.r { grid-column: 2 / 4; text-align: right; }
@container win (max-width: 900px) { .vwin .vside { display: none; } .fnub { left: calc(50% - 4px); } }
@container win (max-width: 720px) { .fnub { left: 50%; } }
@container win (max-width: 720px) { .vtbar b, .vtbar .chev { display: none; } .vtbar { padding-right: 14px; } }

/* ══ Tide in the kit ════════════════════════════════════════════════════════ */
.ttbar { gap: 9px; }
.ttbar .tsrch { flex: 0 1 420px; margin: 0 auto; height: 32px; border-radius: 10px; }
.twin .tside { width: 236px; background: transparent; padding: 2px 10px 10px; }
.twin .tside .sh:first-child { margin-top: 4px; }
.twin .tside .si em { font-style: normal; font-size: 11.5px; color: var(--ink-4); font-variant-numeric: tabular-nums; letter-spacing: .01em; }
.twin .tside .si .cv { width: 24px; border-radius: 6px; box-shadow: 0 0 0 .5px rgba(0,0,0,.3); }
.twin .tmain { isolation: isolate; }
.twin .twash { height: 460px; }
.twin .tr.cur { background: var(--chip); box-shadow: var(--chip-edge); } .twin .tr.cur .t { color: var(--tint); }
.twin .hero > .cv { box-shadow: 0 0 0 .5px rgba(0,0,0,.25), 0 30px 60px -20px rgba(0,0,0,.7), 0 0 90px -10px oklch(0.6 0.12 var(--ah) / .45); }
.twin .feature, .twin .acard .cv { box-shadow: var(--chip-edge); }
.twin .panel.tq { top: 12px; bottom: 12px; right: 12px; background: var(--pop); box-shadow: var(--bar-edge); backdrop-filter: none; }
.twin .panel.tq .qi.cur { background: var(--chip); box-shadow: var(--chip-edge); }
.twin .now { inset: 0; border-radius: 0; }
.twin .now .tabs2 { --well: rgba(0,0,0,.28); --well-edge: inset 0 0 0 1px rgba(0,0,0,.3); --chip: rgba(255,255,255,.92); --chip-edge: 0 1px 2px rgba(0,0,0,.3); --ink: #111; --ink-3: rgba(255,255,255,.75); }
/* The player sits on the frame, lit by the album: the one place the frame takes a colour. */
.twin .player { position: relative; height: 78px; padding: 0 18px 4px 14px; background: transparent; box-shadow: none; isolation: isolate; }
.twin .player::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none; transition: background .6s ease;
  background: radial-gradient(420px 120% at 0% 60%, oklch(0.5 0.1 var(--ah) / .5), transparent 70%), linear-gradient(90deg, oklch(0.45 0.08 var(--ah) / .22), transparent 60%); }
[data-mode="light"] .twin .player::before { background: radial-gradient(420px 120% at 0% 60%, oklch(0.85 0.08 var(--ah) / .7), transparent 70%); }
[data-mode="dark"] .twin .player { --tint: oklch(0.8 0.1 var(--ah)); } [data-mode="light"] .twin .player { --tint: oklch(0.5 0.12 var(--ah)); }
.twin .cvbtn { width: 54px; } .twin .cvbtn .cv { border-radius: 9px; box-shadow: 0 0 0 .5px rgba(0,0,0,.3), 0 6px 16px -6px rgba(0,0,0,.6); }
