.win .fbar .bt.fill { background: transparent; box-shadow: none; } .win .fbar .bt.fill:hover { background: var(--fill-1); }
/* A picker in a bar (text style, format, filter) is a well with a small chevron, like a closed dropdown */
.win .fbar .bt:is(.stylebtn, .nstyle, .fpchip, .grfmt) { gap: 8px; justify-content: space-between; padding: 0 10px 0 12px; background: var(--well); box-shadow: var(--well-edge); color: var(--ink); font-weight: 500; }
.win .fbar .bt:is(.stylebtn, .nstyle, .fpchip, .grfmt):hover { background: var(--well); color: var(--ink); filter: brightness(1.12); } .win .fbar :is(.stylebtn, .nstyle, .fpchip, .grfmt) svg.i { width: 13px; height: 13px; color: var(--ink-3); }
.win .fbar .bt.key[disabled] { opacity: .45; filter: none; }
/* Wells are where you type, or pick one of several */
.win .srch, .win .fbar .seg { height: 36px; border-radius: 12px; background: var(--well); box-shadow: var(--well-edge); color: var(--ink-3); }
.win .srch:hover { background: var(--well); color: var(--ink-2); } .win .srch:focus-within { box-shadow: var(--well-edge), 0 0 0 2px var(--acc-ink); }
.win .seg { background: var(--well); box-shadow: var(--well-edge); } .win .seg .ind { background: var(--chip); box-shadow: var(--chip-edge); }
/* The key: the one thing this screen is for */
.win .bt.key, .win .bt.pri { background: var(--key); color: var(--key-ink); box-shadow: var(--key-edge); font-weight: 600; }
.win .bt.key:hover, .win .bt.pri:hover { background: var(--key); filter: brightness(1.04); }
/* The bar's first word: a raised chip saying what it's working on */
.win .fbar :is(.ctxc, .fpreq, .who):not(.merec) { display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 12px 0 10px; border-radius: 12px; background: var(--chip); box-shadow: var(--chip-edge); color: var(--ink); font-weight: 600; white-space: nowrap; }
.win .fbar .who { padding-left: 4px; } .win .fbar .who .th { width: 28px; height: 28px; border-radius: 8px; } .win .fbar .who span { font-weight: 500; }
.win .fbar .grctx { font: 600 13px var(--font); } .win .fbar :is(.ctxc, .fpreq) > svg.i { width: 15px; height: 15px; color: var(--ink-3); flex: none; } .win .fbar .ctxc em { font-style: normal; font-weight: 500; color: var(--ink-3); }
/* Filer: selection is the same raised chip as everywhere; Information docks beside the files; a column view */
#w-filer .tile.on { background: var(--chip); box-shadow: var(--chip-edge); } #w-filer .flist tr.on td { background: var(--chip); }
.fdock { width: 0; flex: none; overflow: hidden; margin: 12px 0; border-radius: 16px; background: var(--well); box-shadow: var(--well-edge); opacity: 0; display: flex; flex-direction: column; transition: width .3s var(--ease), margin .3s var(--ease), opacity .2s; }
#w-filer.finfo .fdock { width: 272px; margin: 0 8px 8px 0; opacity: 1; }

/* The sidebar head, everywhere: a real search field, and New as a raised square beside it. Other things to create use the + on their section header. */
.shead { display: flex; align-items: center; gap: 6px; padding: 2px 0 6px; }
/* ...at the foot of the sidebar, like the filter drawers: a hairline above, then search and New */
.shead.sfoot { flex: none; margin: 8px 0 0; padding: 8px 0 0; }
.shead .srch { flex: 1; width: auto; min-width: 0; height: 34px; border-radius: 11px; }
.shead .srch .fqx { margin-right: -4px; }
.snew { width: 34px; height: 34px; flex: none; display: grid; place-items: center; border-radius: 11px; background: var(--chip); box-shadow: var(--chip-edge); color: var(--ink); } .snew:hover { filter: brightness(1.08); } .snew svg.i { width: 16px; height: 16px; }
/* An item's on/off state (Pin, Star) lights its icon; no plate behind it */
.nfloat .ib.lit { color: var(--acc-ink); background: none; box-shadow: none; } .nfloat .ib.lit svg.i { fill: currentColor; fill-opacity: .25; }

/* Contacts: a file shared with them is the LumaUI file card, full width in Together */
