.cgrid { align-items: start; } .ctog { display: flex; flex-direction: column; min-height: 0; }
/* Contacts (v70): side by side, Together takes the row height the Contact card sets (contain: size keeps its own list from
   sizing the row) and scrolls inside; it is never shorter than 200. Stacked, it's as tall as what it holds. */
.cgrid > .ctog { align-self: stretch; contain: size; min-height: 200px; } @container win (max-width: 900px) { .cgrid > .ctog { contain: none; min-height: 0; } .ctog .tgl { max-height: 320px; } }
.chero > .lcacts { width: 100%; max-width: 376px; margin: 22px auto 0; } .cwin .pop .mi.danger, .cwin .pop .mi.danger svg.i { color: var(--lui-danger); } #c-float .bt > span { white-space: nowrap; } .win.phone #c-float .bt[data-share] > span, .win.phone #c-float .bt[data-cmycode] > span { display: none; } .win.phone #c-float .bt[data-share], .win.phone #c-float .bt[data-cmycode] { width: 36px; padding: 0; justify-content: center; } .ctog .tgl { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; mask-image: linear-gradient(180deg, #000 calc(100% - 24px), transparent); padding-bottom: 12px; }
.cwin .mi.danger:hover svg.i, .nwin .mi.danger:hover svg.i { color: oklch(0.72 0.17 25); }
