#w-photos .pc[data-r~="tl"] { border-top-left-radius: 12px; } #w-photos .pc[data-r~="tr"] { border-top-right-radius: 12px; } #w-photos .pc[data-r~="br"] { border-bottom-right-radius: 12px; } #w-photos .pc[data-r~="bl"] { border-bottom-left-radius: 12px; }
#p-corner .ib.faved svg.i { color: oklch(0.66 0.2 15); fill: currentColor; } #p-det .pdockt { margin: 0 0 10px; } :is(#p-corner, #vw-corner)[hidden] { display: none !important; } #w-photos.phone .viewer { padding-top: 132px; } #w-photos.phone .viewer .vt { top: 74px; left: 24px; }
#w-photos.viewing .fbar { --ink: #f3f3f2; --ink-2: rgba(255,255,255,.82); --ink-3: rgba(255,255,255,.62); } .pside .si em.lcount { margin-left: auto; font-size: 11px; color: var(--ink-2); }
.psize { display: flex; align-items: center; gap: 8px; padding: 0 8px; color: var(--ink-3); } .psize svg.i { width: 15px; height: 15px; } .psize input { width: 112px; }
