.pimps { display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; margin: 10px 0; } .pimps img, .pimps span { width: 100%; aspect-ratio: 1; object-fit: cover; border-radius: 7px; } .pimps span { display: grid; place-items: center; background: var(--fill-2); font-size: 12px; font-weight: 600; color: var(--ink-2); letter-spacing: .01em; }
