.deck .dmid { display: block; } .dtx .dtl { display: flex; align-items: center; gap: 2px; min-width: 0; } .dtx .dtl b { min-width: 0; }
.deck .dlove { width: 28px; height: 28px; flex: none; color: var(--ink-3); } .deck .dlove svg.i { width: 15px; height: 15px; } .deck .dlove.loved { color: var(--love); } .deck .dlove.loved svg.i { fill: currentColor; }
.dctlw { position: relative; z-index: 1; display: grid; justify-items: center; gap: 2px; } .dctlw .dctl { gap: 6px; } .deck .pp { width: 44px; height: 44px; }
