.tsrcgo { display: flex; justify-content: flex-end; margin-top: 16px; } .tsrcgo .bt.key { height: 36px; padding: 0 18px; border-radius: 12px; background: var(--key); color: var(--key-ink); box-shadow: var(--key-edge); font-weight: 600; }
.tpane .qlab { margin: 14px 0 4px; font: var(--t-label); letter-spacing: .01em; color: var(--ink-3); } .tpane .ldplab + .tqlist .qi.cur { background: var(--fill-1); }
.songs .tr.th.lthgrid, .songs .tr.th.lthgrid:hover { height: 30px; margin-bottom: 6px; background: var(--fill-1); } .songs .tr.th.lthgrid > button:nth-child(2) { margin-left: 0; }
