@container win (max-width: 720px) { .twin .tmain .ttl.tttl { padding: 74px 20px 8px; } .deck { grid-template-columns: minmax(0, 1fr) auto; gap: 8px; } .deck .dctlw .scrub, .deck .dctl .ib.wide, .deck .dlove { display: none; } .twin .deck { padding-right: 14px; } }
