/* ══ LumaUI components (v70, from the Studio audit of 25 Sep) ═══════════════════════════════════
   The shared parts every app uses. One implementation each, light and dark, keyboard and phone.
   Each part is its own block labelled "LumaUI: <component>" so per-app branches merge cleanly.
   The LumaUI window (?app=lumaui) shows every part with its states; the JS helpers sit beside lFile. */

/* LumaUI: Tokens (danger ink, category hues, sky cards) */
[data-mode="dark"] .win { --lui-danger: oklch(0.7 0.17 25); }
[data-mode="light"] .win { --lui-danger: oklch(0.55 0.19 25); }
:root { --cat-create: 25; --cat-work: 250; --cat-media: 330; --cat-play: 150; --cat-tools: 200;
  --card-sky: oklch(0.2 0.035 255 / .42); --card-sky-edge: inset 0 0 0 1px rgba(255,255,255,.12), inset 0 1px 0 rgba(255,255,255,.1); --card-sky-ink-2: rgba(255,255,255,.9); }

/* LumaUI: Type scale
   Figtree only; five roles plus the small label, each with one size, weight and tracking. Numbers that change are tabular.
   No one-off weights, sizes or letter-spacing: use these. */
:root { --t-display: 600 72px/1 var(--font); --t-title-1: 650 24px/1.15 var(--font); --t-title-2: 650 15px/1.3 var(--font); --t-body: 400 13px/1.45 var(--font);
  --t-caption: 500 11.5px/1.35 var(--font); --t-label: 600 11.5px/1.3 var(--font); --t-numeric: 500 30px/1.1 var(--font); }
.t-display { font: var(--t-display); letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
.t-title-1 { font: var(--t-title-1); letter-spacing: -.024em; }
.t-title-2 { font: var(--t-title-2); letter-spacing: -.01em; }
.t-body { font: var(--t-body); letter-spacing: -.006em; }
.t-caption { font: var(--t-caption); letter-spacing: .01em; color: var(--ink-3); }
.t-label { font: var(--t-label); letter-spacing: .01em; color: var(--ink-3); }
.t-numeric { font: var(--t-numeric); letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
:is(.t-display, .t-numeric) small { margin-left: .12em; font-size: .4em; font-weight: 500; letter-spacing: 0; color: var(--ink-3); }   /* seconds, AM/PM, units */

/* LumaUI: Count badge
   A small pill with tabular numbers: neutral for totals, .acc for unread or needs attention. Never 0. */
:is(em, i, span, b).lcount { display: inline-grid; place-items: center; flex: none; min-width: 20px; height: 18px; padding: 0 6px; border-radius: 9px; corner-shape: round;
  font: 650 11px/1 var(--font); font-style: normal; font-variant-numeric: tabular-nums; letter-spacing: .01em; background: var(--fill-2); color: var(--ink-2); }
:is(em, i, span, b).lcount.acc { background: oklch(0.52 0.15 var(--acc)); color: #fff; }
.seg .lcount { margin-left: 6px; } .seg button:not(.on) .lcount.acc { background: oklch(0.52 0.15 var(--acc)); }

/* LumaUI: Details pane
   One pane for Details and Information in every app: recessed into the frame like the island (same top, 8 from the edges),
   a header with a hairline under it and a close button, one scrolling body. Key/value facts get hairlines; lists of people
   or things get none, but every row highlights across its full width. Closed by default, opened by Info, closes itself
   when its subject goes away (data-main keeps a pane that is the app's main view, like Calendar's day). On a phone it is a drawer. */
.ldp { --ldp-w: 288px; position: relative; flex: none; width: var(--ldp-w); min-height: 0; display: flex; flex-direction: column; margin: 0 8px 8px 0; overflow: hidden;
  border-radius: 12px; background: var(--isle); box-shadow: var(--isle-out); color: var(--ink); }
.ldp::after { content: ""; position: absolute; inset: 0; z-index: 3; border-radius: inherit; pointer-events: none; box-shadow: var(--isle-in); }
.ldp[hidden] { display: none; } .ldp.enter { animation: ldpin .3s var(--ease); } @keyframes ldpin { from { opacity: 0; transform: translateX(14px); } }
#w-filer .fdock.ldp { width: var(--ldp-w); margin: 0 8px 8px 0; opacity: 1; }
.ldph { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 8px; height: 48px; padding: 0 8px 0 16px; border-bottom: 1px solid var(--hair); }
.ldph b { font: var(--t-title-2); font-size: 14px; letter-spacing: -.01em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ldph .ib { width: 30px; height: 30px; border-radius: 9px; color: var(--ink-3); } .ldph .ib:hover { color: var(--ink); } .ldph .ib svg.i { width: 16px; height: 16px; }
.ldpb { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; padding: 14px 16px 16px; } .ldpb::-webkit-scrollbar { display: none; }
.ldplab { display: flex; align-items: center; gap: 8px; margin: 20px 0 6px; font: var(--t-label); letter-spacing: .01em; color: var(--ink-3); } .ldpb > .ldplab:first-child { margin-top: 2px; }
.ldplab > button { margin-left: auto; height: 24px; padding: 0 8px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--acc-ink); } .ldplab > button:hover { background: var(--fill-1); }
.ldpkv { margin: 0; display: grid; } .ldpkv > div { display: flex; justify-content: space-between; gap: 12px; padding: 7px 0; font-size: 12.5px; border-top: 1px solid var(--hair); } .ldpkv > div:first-child { border-top: 0; }
.ldpkv dt { flex: none; color: var(--ink-3); } .ldpkv dd { min-width: 0; margin: 0; font-weight: 550; text-align: right; overflow-wrap: anywhere; }
.ldphero { display: grid; justify-items: center; gap: 3px; padding: 6px 0 14px; text-align: center; } .ldphero b { margin-top: 8px; font: var(--t-title-2); font-size: 16px; } .ldphero small { font: var(--t-caption); color: var(--ink-3); letter-spacing: .01em; }
.ldplist { display: grid; margin: 0 -8px; }
.ldprow { position: relative; display: flex; align-items: center; gap: 2px; min-height: 44px; padding: 0 4px 0 0; border-radius: 10px; transition: background .12s; }
.ldprow:hover, .ldprow:focus-within { background: var(--fill-1); }
.ldpwho { flex: 1; min-width: 0; display: flex; align-items: center; gap: 10px; padding: 6px 8px; border-radius: 10px; text-align: left; } .ldpwho:focus-visible { outline-offset: -2px; }
.ldpwho > span { min-width: 0; display: grid; } .ldpwho b { font-size: 13px; font-weight: 550; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ldpwho small { font: var(--t-caption); letter-spacing: .01em; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ldpacts { display: flex; flex: none; opacity: 0; transition: opacity .15s; } .ldprow:hover .ldpacts, .ldprow:focus-within .ldpacts { opacity: 1; }
.ldpacts .ib { width: 28px; height: 28px; border-radius: 8px; color: var(--ink-3); } .ldpacts .ib:hover { color: var(--ink); background: var(--fill-2); } .ldpacts .ib svg.i { width: 15px; height: 15px; }
@media (hover: none) { .ldpacts { opacity: 1; } } .win.phone .ldpacts { opacity: 1; }
.ldpb .lfc { width: 100%; } :is(.ldpb, .dbody) > .lstks { margin-top: 20px; }
/* On a phone the pane is a drawer: full width from the bottom edge, with a handle */
.win.phone .ldp { position: absolute; z-index: 45; left: 0; right: 0; bottom: 0; width: auto; max-height: 78%; margin: 0; border-radius: 28px 28px 0 0; padding-top: 14px;
  background: var(--float-solid); box-shadow: var(--sh-float); animation: ldpup .32s var(--spring); }
#w-filer.phone .fdock.ldp { position: absolute; width: auto; margin: 0; }   /* Filer's older #id rules outrank the class; keep the drawer */
.win.phone .ldp::after { display: none; } .win.phone .ldp::before { content: ""; position: absolute; top: 7px; left: 50%; width: 36px; height: 5px; margin-left: -18px; border-radius: 3px; background: var(--fill-3); }
@keyframes ldpup { from { transform: translateY(40px); opacity: 0; } }

/* LumaUI: Details pane item
   A thing in a details-pane list (an event, a thread): its mark, a title, one quiet line, an optional trail; the same row, hover and type
   as the people rows. lDPItem({ lead, n, sub, attr, style, trail }). */
.ldpitem { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; padding: 6px 8px; border-radius: 10px; text-align: left; transition: background .12s; } .ldpitem:hover, .ldpitem:focus-visible, .ldpitem.on { background: var(--fill-1); } .ldpitem:focus-visible { outline-offset: -2px; }
.ldpitem > svg.i { width: 16px; height: 16px; flex: none; color: var(--ink-3); } .ldpitem > span:not(.nfaces) { flex: 1; min-width: 0; display: grid; } .ldpitem b { font-size: 13px; font-weight: 550; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } .ldpitem small { font: var(--t-caption); letter-spacing: .01em; color: var(--ink-3); font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* LumaUI: Details pane photos
   A conversation's or thread's photos: three square thumbnails a row under "Photos and files", never one giant image. <div class="ldpph"> of <img>. */
.ldpph { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; border-radius: 10px; overflow: hidden; } .ldpph img { display: block; width: 100%; aspect-ratio: 1; object-fit: cover; }

/* LumaUI: Add row
   "Add people", "Add source", "Add account": a list row, not a framed button. The + sits in the avatar column, the label lines up with the names. */
.laddrow { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; padding: 6px 8px; border-radius: 10px; text-align: left; color: var(--ink-2); transition: background .12s; }
.laddrow:hover { background: var(--fill-1); color: var(--ink); } .laddrow:focus-visible { outline-offset: -2px; }
.laddi { width: 32px; height: 32px; flex: none; display: grid; place-items: center; border-radius: 50%; corner-shape: round; background: var(--fill-1); box-shadow: inset 0 0 0 1px var(--hair); color: var(--ink-2); } .laddi svg.i { width: 15px; height: 15px; }
.laddrow b { font-size: 13px; font-weight: 550; }
.laddrow kbd { margin-left: auto; font: 500 11px var(--font); color: var(--ink-4); letter-spacing: .01em; } .win.phone .laddrow kbd { display: none; }   /* a shortcut, shown the menus' way (none on a phone) */

/* LumaUI: Stacked button
   Icon on top, label below, on the raised chip (the Contacts action look). Always in equal pairs or trios; .sm for tight panes;
   .danger for destructive (red ink, still confirmed); hover lifts, press sinks, focus rings, disabled fades. */
.lstks { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 8px; }
.lstk { min-width: 0; height: 64px; display: grid; justify-items: center; align-content: center; gap: 5px; padding: 0 6px; border-radius: 16px; font: 500 12px/1.2 var(--font); letter-spacing: .01em;
  color: var(--ink); background: var(--chip); box-shadow: var(--chip-edge); transition: transform .15s var(--spring), filter .12s; }
.lstk > span { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } .lstk svg.i { width: 19px; height: 19px; }
.lstk:hover { transform: translateY(-1px); filter: brightness(1.07); } [data-mode="light"] .lstk:hover { filter: brightness(.98); } .lstk:active { transform: scale(.97); filter: brightness(.95); }
.lstk:focus-visible { outline: 2px solid var(--acc-ink); outline-offset: 2px; } .lstk[disabled] { opacity: .35; pointer-events: none; }
.lstk.danger { color: var(--lui-danger); }
.lstks.sm .lstk { height: 56px; gap: 4px; padding: 0 2px; border-radius: 14px; font-size: 11.5px; } .lstks.sm .lstk svg.i { width: 17px; height: 17px; }
/* LumaUI: Contact actions (Contacts owns them: Message, Call, Video, Email, in that order) */
.lcacts { max-width: 376px; }

/* LumaUI: Selection bubble (.selbar, from Write)
   Floats 10 above the selection, centred and kept inside its host; flips below near the top edge. Arrows move inside it, Esc hides it. */
.selbar.below { animation: morph .14s var(--ease); } .selbar .ib:focus-visible, .selbar .bt:focus-visible { outline-offset: -2px; }
.win.phone .selbar .wrsel { display: none; }

/* LumaUI: Action center
   The floating bar is where you act, and it grows in place: the bar (.fbar), double height (.fbar.lac2: a context line over the bar),
   the full editor (.lac: Charlie's reply, ported exactly), or split in two (.lacsplit). It caps at the island and its text scrolls.
   Esc collapses it back to the bar and keeps what you typed. On a phone it spans the width from the bottom edge. */
.fbar.lac2 { flex-direction: column; align-items: stretch; gap: 2px; width: min(700px, calc(100% - 48px)); white-space: normal; }
.lacrow { display: flex; align-items: center; gap: 4px; min-width: 0; }
.lacctx { display: flex; align-items: center; gap: 8px; min-width: 0; padding: 4px 6px 4px 10px; font: var(--t-caption); font-size: 12px; color: var(--ink-2); letter-spacing: .01em; }
.lacctx > svg.i { width: 13px; height: 13px; color: oklch(0.72 0.11 var(--acc)); flex: none; } .lacctx span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } .lacctx b { color: var(--ink); font-weight: 600; }
.lacfield { flex: 1; min-width: 0; height: 36px; padding: 0 12px; border-radius: 12px; background: var(--well); box-shadow: var(--well-edge); color: var(--ink-3); text-align: left; font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; cursor: text; } .lacfield:hover { color: var(--ink-2); }
.lac { position: absolute; left: 50%; bottom: 20px; z-index: 30; width: min(720px, calc(100% - 48px)); max-height: calc(100% - 40px); transform: translateX(-50%); display: flex; flex-direction: column;
  border-radius: 20px; background: var(--pop, var(--float-solid)); box-shadow: var(--sh-float), inset 0 0 0 1px var(--hair); transition: left .3s var(--ease); }
.lac[hidden] { display: none; } .lac.enter { animation: lacup .32s var(--spring); } @keyframes lacup { from { opacity: 0; transform: translate(-50%, 16px) scale(.98); } }
.lach { flex: none; display: flex; align-items: center; gap: 10px; height: 48px; padding: 0 8px; border-bottom: 1px solid var(--hair); }
.lach .lacmode { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 10px 0 9px; border-radius: 10px; background: var(--chip); box-shadow: var(--chip-edge); font-size: 12.5px; font-weight: 600; flex: none; }
.lach .lacmode svg.i { width: 14px; height: 14px; color: var(--acc-ink); } .lach > span { flex: 1; min-width: 0; font-size: 12.5px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } .lach > span b { color: var(--ink-2); font-weight: 600; }
.lacf { flex: none; display: flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 14px; border-bottom: 1px solid var(--hair); }
.lacf label { width: 56px; flex: none; font-size: 12.5px; color: var(--ink-3); } .lacf input { flex: 1; min-width: 60px; height: 32px; border: 0; outline: 0; background: none; color: var(--ink); font: 13.5px var(--font); } .lacf input::placeholder { color: var(--ink-3); }
.lactools { flex: none; display: flex; align-items: center; gap: 2px; padding: 6px 8px 2px; } .lactools .ib { width: 32px; height: 32px; border-radius: 9px; color: var(--ink-2); } .lactools .ib:hover { background: var(--fill-1); color: var(--ink); } .lactools .ib svg.i { width: 16px; height: 16px; }
.lactools .vr { width: 1px; height: 18px; margin: 0 4px; background: var(--hair); } .lac .sp { flex: 1; }
.laced { flex: 1 1 auto; min-height: 132px; max-height: 40vh; overflow-y: auto; scrollbar-width: none; padding: 8px 16px 14px; outline: none; font-size: 14px; line-height: 1.55; overflow-wrap: anywhere; }
.laced:empty::before { content: attr(data-ph); color: var(--ink-3); pointer-events: none; }
.lacft { flex: none; display: flex; align-items: center; gap: 10px; padding: 8px; border-top: 1px solid var(--hair); } .lacft .ib { width: 36px; height: 36px; border-radius: 12px; color: var(--ink-3); }
.lacft small { font-size: 11.5px; color: var(--ink-4); letter-spacing: .01em; } .lacft .bt.key { height: 36px; gap: 7px; padding: 0 16px; border-radius: 12px; background: var(--key); color: var(--key-ink); box-shadow: var(--key-edge); font-weight: 600; } .lacft .bt.key svg.i { width: 15px; height: 15px; }
.lacsplit { position: absolute; left: 50%; bottom: 16px; z-index: 20; display: flex; align-items: flex-end; gap: 8px; max-width: calc(100% - 24px); transform: translateX(-50%); }
.lacsplit > .fbar { position: relative; left: auto; bottom: auto; transform: none; max-width: none; }
.win.phone .lac { left: 0; right: 0; bottom: 0; width: auto; max-height: calc(100% - 60px); transform: none; border-radius: 22px 22px 0 0; } .win.phone .lac.enter { animation: none; }
.win.phone .fbar.lac2 { width: calc(100% - 16px); } .win.phone .lacsplit { left: 8px; right: 8px; transform: none; flex-direction: column; align-items: stretch; } .win.phone .lacsplit > .fbar { width: 100%; justify-content: center; }

/* LumaUI: Placement (top right = modes and the thing itself; bottom bar = what you do right now)
   .lcorner is the top-right pill: the mode switch, then Open in, Share, Edit, Info and ···. Modes are .lmodes: icon plus label;
   on a narrow window only the current mode keeps its label. */
.win .flo.lcorner { position: absolute; top: 16px; right: 16px; z-index: 26; display: flex; align-items: center; }
.lcorner .seg { height: 36px; background: var(--well); box-shadow: var(--well-edge); border-radius: 12px; } .lcorner .seg .ind { border-radius: 9px; background: var(--chip); box-shadow: var(--chip-edge); } .lcorner .seg button { height: 30px; border-radius: 9px; }
.lmodes button svg.i { width: 15px; height: 15px; }
@container win (max-width: 820px) { .lmodes button:not(.on) span { display: none; } .lmodes button:not(.on) { padding: 0 9px; } }
/* Viewer (reference): the markup tools rise above the bar they belong to, so the top right stays the corner's */
#vw-pal.vwpal { top: auto; bottom: 76px; transform: translate(-50%, 12px); } #vw-pal.vwpal.on { transform: translate(-50%, 0); }

/* LumaUI: Open in
   The Open button wears the default app's own icon ("Open in Stage"); the Open in menu lists the apps that can open the file,
   best Luma app first, the default marked, then Other app. */
.lappi { width: 18px; height: 18px; flex: none; border-radius: 5px; } .crmi .lappi { width: 20px; height: 20px; }
.lopenb .lappi { margin-left: -2px; } .lfc .lopenb { gap: 6px; padding-left: 8px; } .lfc .lopenb .lappi { width: 16px; height: 16px; border-radius: 4px; }
/* LumaUI: Menu drawer. Every shared menu (lMenu: Open in, the sidebar-foot filter, ···, style and zoom menus) is the usual popover on a
   computer and a bottom drawer on a phone: full width, a grab handle, rows sized for a thumb, the window dimmed behind it */
.win.phone :is(#lmenu, .crpop.ldrawer) { left: 0 !important; right: 0; top: auto !important; bottom: 0; width: auto; min-width: 0; max-height: 72%; overflow-y: auto; padding: 26px 10px 16px; border-radius: 28px 28px 0 0; box-shadow: 0 0 0 100vmax oklch(0 0 0 / .32), var(--sh-float); animation: ldrawer .26s var(--ease); }
.win.phone :is(#lmenu, .crpop.ldrawer)::before { content: ""; position: absolute; top: 9px; left: 50%; width: 36px; height: 5px; margin-left: -18px; border-radius: 3px; background: var(--fill-3); }
.win.phone :is(#lmenu, .crpop.ldrawer) .crmi { min-height: 46px; } .win.phone :is(#lmenu, .crpop.ldrawer) h6 { margin: 0 16px 6px; }
@keyframes ldrawer { from { transform: translateY(48px); opacity: 0; } }
.lopenmenu { min-width: 232px; } .lopenmenu .crmi > small { margin-left: auto; font-size: 11px; color: var(--ink-3); letter-spacing: .01em; }

/* LumaUI: Sidebar toggle
   lSideBtn(win) in the title bar, just after the app's name: Lucide panel-left, F9; pressed while the sidebar shows. Each app says what
   "closed" means (Viola keeps a strip of tab icons; the others give the room to the content). On a phone it opens the sidebar as a drawer. */
.tbar .lsidebtn { width: 30px; height: 30px; flex: none; border-radius: 9px; color: var(--ink-3); } .tbar .lsidebtn:hover { color: var(--ink); background: var(--fill-1); } .tbar .lsidebtn svg.i { width: 16px; height: 16px; }
.tbar .lsidebtn[aria-pressed="false"] { color: var(--ink-2); } .win.phone:has(.navbtn, .navback) .tbar .lsidebtn { display: none !important; }
/* LumaUI: Message bubble
   Messages owns the look and every thread uses it (Messages, Charlie): theirs is the raised chip, yours the accent gradient (--mbub) in white;
   18 round, 6 where one sender's run joins; 9/13/10 padding; 14/1.45 text. Use the tokens, never a local radius or size. */
:root { --lbub-r: 18px; --lbub-join: 6px; --lbub-pad: 9px 13px 10px; --lbub-text: 400 14px/1.45 var(--font); }
:where([data-mode="dark"]) :where(.win) { --mbub: linear-gradient(180deg, oklch(0.52 0.12 var(--acc)), oklch(0.46 0.12 var(--acc))); --mbub-ink: #fff; --mbub-edge: inset 0 1px 0 oklch(1 0 0 / .18), 0 0 0 1px rgba(0,0,0,.35), 0 1px 2px rgba(0,0,0,.3); }
:where([data-mode="light"]) :where(.win) { --mbub: linear-gradient(180deg, oklch(0.6 0.13 var(--acc)), oklch(0.54 0.13 var(--acc))); --mbub-ink: #fff; --mbub-edge: inset 0 1px 0 oklch(1 0 0 / .25), 0 0 0 1px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.12); }

/* LumaUI: File card (lFile)
   The file's face (never bigger than its 44 square), a middle-truncated name that keeps the extension, size · kind, one Open. */
.lfc .lfth > img { max-width: 44px; max-height: 44px; } .lfc { max-width: 100%; }
.lmid { display: flex !important; min-width: 0; } .lmid > span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } .lmid > span + span { flex: none; white-space: pre; }
.lfc .lfbad { color: var(--lui-danger); } .lfc .lfwarn { color: oklch(0.72 0.14 70); } [data-mode="light"] .lfc .lfwarn { color: oklch(0.55 0.14 60); }

/* LumaUI: Destructive dialog
   Centred on the asking window, which dims under its title bar: icon on top, the question as the title, one line of consequence,
   Cancel and the red action as two equal buttons. Cancel has focus (Enter never deletes by accident); Esc cancels. A drawer on a phone. */
.lcscrim { position: absolute; left: 0; right: 0; top: 46px; bottom: 0; z-index: 60; background: rgba(0,0,0,.26); backdrop-filter: blur(3px) saturate(.9); -webkit-backdrop-filter: blur(3px) saturate(.9); opacity: 0; transition: opacity .2s var(--ease); }
[data-mode="light"] .lcscrim { background: rgba(20,20,30,.12); } .lcscrim.on { opacity: 1; }
.lconf { position: absolute; left: 50%; top: 50%; z-index: 61; width: 340px; max-width: calc(100% - 32px); padding: 24px 20px 20px; border-radius: 20px; text-align: center; color: var(--ink);
  background: var(--pop, var(--float-solid)); box-shadow: var(--sh-float), inset 0 1px 0 var(--hi), 0 0 0 1px var(--hair); opacity: 0; transform: translate(-50%, -46%) scale(.96); transition: opacity .16s ease, transform .36s var(--spring); }
.lconf.on { opacity: 1; transform: translate(-50%, -50%); } .lconf.nudge { animation: lcnudge .3s var(--ease); } @keyframes lcnudge { 30% { margin-left: -6px; } 70% { margin-left: 6px; } }
.lcico { width: 52px; height: 52px; margin: 0 auto 14px; display: grid; place-items: center; border-radius: 16px; background: var(--chip); box-shadow: var(--chip-edge); color: var(--lui-danger); } .lcico svg.i { width: 24px; height: 24px; }
.lconf h2 { margin: 0; font: var(--t-title-2); font-size: 16px; line-height: 1.35; letter-spacing: -.01em; } .lconf p { margin: 6px 0 0; font-size: 13.5px; line-height: 1.5; color: var(--ink-2); }
.lcopt { display: inline-flex; align-items: center; gap: 9px; height: 32px; margin-top: 12px; padding: 0 10px 0 8px; border-radius: 10px; font-size: 13px; color: var(--ink-2); } .lcopt:hover { background: var(--fill-1); }
.lcopt i { width: 16px; height: 16px; display: grid; place-items: center; border-radius: 5px; box-shadow: inset 0 0 0 1.5px var(--ink-3); } .lcopt i svg.i { width: 11px; height: 11px; stroke-width: 3; opacity: 0; }
.lcopt[aria-checked="true"] i { background: oklch(0.6 0.13 var(--acc)); box-shadow: none; color: #fff; } .lcopt[aria-checked="true"] i svg.i { opacity: 1; }
.lcacts2 { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 20px; } .lcacts2 .bt { justify-content: center; height: 36px; border-radius: 12px; font-weight: 600; }
.lconf .bt.fill { background: var(--fill-2); } .lconf .bt.fill:hover { background: var(--fill-3); }
.lconf .bt.danger { background: linear-gradient(180deg, oklch(0.64 0.19 25), oklch(0.56 0.19 25)); color: #fff; box-shadow: inset 0 1px 0 rgba(255,255,255,.2), 0 0 0 1px rgba(0,0,0,.25), 0 1px 2px rgba(0,0,0,.3); } .lconf .bt.danger:hover { filter: brightness(1.08); }
.lconf .bt:focus-visible { outline: 2px solid oklch(0.72 0.12 var(--acc) / .7); outline-offset: 2px; }
.win.phone .lconf { top: auto; bottom: 0; left: 0; width: auto; max-width: none; right: 0; padding: 30px 20px 26px; border-radius: 28px 28px 0 0; transform: translateY(30px); }
.win.phone .lconf.on { transform: none; } .win.phone .lconf::before { content: ""; position: absolute; top: 8px; left: 50%; width: 36px; height: 5px; margin-left: -18px; border-radius: 3px; background: var(--fill-3); }
.win.phone .lcacts2 { grid-template-columns: 1fr; } .win.phone .lcacts2 .bt { height: 44px; } .win.phone .lcacts2 .danger { order: -1; }

/* LumaUI: Toast (.ftoast.ltoast, via lToast)
   One place: centred on the visible content, just above the bottom bar. A plain past-tense line, the icon for what happened, Undo when it can be undone. */
.win > .ltoast { z-index: 60; } .ftoast[data-kind="map-pin"] > svg.i, .ftoast[data-kind="navigation"] > svg.i { color: var(--acc-ink); } .ftoast[data-kind="heart"] > svg.i { color: var(--love); fill: currentColor; }
.ftoast:is([data-kind="copy"], [data-kind="trash-2"], [data-kind="bell"], [data-kind="download"], [data-kind="archive"], [data-kind="log-out"]) > svg.i { color: var(--ink-2); }
.win.phone > .ltoast { max-width: calc(100% - 24px); }

/* LumaUI: Category pill
   Depot's categories carry their colour everywhere a category shows: one map (--cat-*), light and dark, AA text. */
:is(span, em, b).lcat { --ch: 250; display: inline-flex; align-items: center; flex: none; min-height: 0; overflow: visible; height: 22px; padding: 0 9px; border-radius: 11px; corner-shape: round; font: 600 11.5px/1 var(--font); font-style: normal; letter-spacing: .01em; white-space: nowrap;
  background: oklch(0.93 0.045 var(--ch)); color: oklch(0.42 0.12 var(--ch)); }
[data-mode="dark"] .lcat { background: oklch(0.34 0.065 var(--ch)); color: oklch(0.88 0.07 var(--ch)); }
.lcat[data-cat="create"] { --ch: var(--cat-create); } .lcat[data-cat="work"] { --ch: var(--cat-work); } .lcat[data-cat="media"] { --ch: var(--cat-media); } .lcat[data-cat="play"] { --ch: var(--cat-play); } .lcat[data-cat="tools"] { --ch: var(--cat-tools); }
.dcard > .lcat { position: absolute; top: 14px; right: 14px; }

/* LumaUI: Table header
   A subtle recessed bar across the columns. Each heading is a button: click or Enter sorts, again reverses; the active column
   shows its arrow and aria-sort says so. Rows start 6 below it. */
.lthead th { height: 30px; padding: 0; border: 0; background: var(--fill-1); text-align: left; font-weight: inherit; }
.lthead th:first-child { border-radius: 10px 0 0 10px; } .lthead th:last-child { border-radius: 0 10px 10px 0; }
.lthead th > button { display: flex; align-items: center; gap: 4px; width: 100%; height: 30px; padding: 0 12px; border-radius: inherit; font: var(--t-label); letter-spacing: .01em; color: var(--ink-3); white-space: nowrap; }
.lthead th > button:hover, .lthead th:not([aria-sort="none"]) > button { color: var(--ink); } .lthead th > button svg.i { width: 12px; height: 12px; stroke-width: 2.2; } .lthead th > button:focus-visible { outline-offset: -2px; }
.lthead + tbody tr:first-child td { border-top: 6px solid transparent; background-clip: padding-box; }

/* LumaUI: Selection
   One selection look: the raised chip. In a path (column view) the steps before the active column keep the same shape as a quieter trail. */
.lsel, #w-filer :is(.tile.on, .fcrow.on) { background: var(--chip); box-shadow: var(--chip-edge); color: var(--ink); }
.ltrail, #w-filer .fcrow.trail { background: var(--fill-2); box-shadow: none; color: var(--ink); }

/* LumaUI: Sidebar foot
   Search at the foot of the sidebar (above a hairline), then a filter picker (lit when a filter is on; its menu opens upward)
   or the raised New square. A filtered list names its filter at the top, with Show all. */
.lfoot { position: relative; } .lfilt.on { color: var(--acc-ink); box-shadow: var(--chip-edge), inset 0 0 0 1.5px color-mix(in oklch, var(--acc-ink) 50%, transparent); }
.lfhead { display: flex; align-items: center; gap: 8px; margin: 2px 2px 6px 8px; font: var(--t-label); letter-spacing: .01em; color: var(--ink-2); } .lfhead span { flex: 1; }
.lfhead button { height: 24px; padding: 0 8px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--acc-ink); } .lfhead button:hover { background: var(--fill-1); }

/* LumaUI: Place search
   The field at the sidebar foot is the whole flow: resolved places open above it as you type, Enter or a click adds the top or
   chosen one, and no match says so in the list. */
.lsug { position: absolute; left: 0; right: 0; bottom: calc(100% + 6px); z-index: 30; display: grid; gap: 1px; padding: 4px; border-radius: 14px; background: var(--pop, var(--float-solid)); box-shadow: var(--sh-float), inset 0 0 0 1px var(--hair); animation: crpop .16s var(--ease); }
.lsug[hidden] { display: none; }
.lsugi { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 42px; padding: 4px 10px; border-radius: 10px; text-align: left; } .lsugi:hover, .lsugi.on { background: var(--fill-1); }
.lsugi > svg.i { width: 16px; height: 16px; flex: none; color: var(--ink-3); } .lsugi span { flex: 1; min-width: 0; display: grid; } .lsugi b { font-size: 13px; font-weight: 550; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lsugi small { font: var(--t-caption); letter-spacing: .01em; color: var(--ink-3); } .lsugi kbd { font: 500 11px var(--font); color: var(--ink-4); letter-spacing: .01em; }
.lsugnone { margin: 8px 10px; font-size: 12.5px; color: var(--ink-3); }

/* LumaUI: Account card
   The person at the top of a sidebar sits in its own subtle frame, a section gap above the list; it opens the account page. */
.lacct { display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 10px 10px 10px; margin: 0 0 14px; border-radius: 14px; background: var(--fill-1); box-shadow: inset 0 0 0 1px var(--hair); text-align: left; }
.lacct:hover { background: var(--fill-2); } .lacct.on { background: var(--chip); box-shadow: var(--chip-edge); } .lacct > span { flex: 1; min-width: 0; } .lacct > svg.i:last-child { width: 15px; height: 15px; color: var(--ink-4); }

/* LumaUI: Cards on content-lit backgrounds
   On a light sky or photo, a card sits darker than what's behind it (a deep blue-black frost at 42%: the least that passes AA for
   90% white on the brightest sky, measured) so white text passes AA;
   secondary text in it is 90% white. Where colour means nothing, use a plain .lcard. */
.lskycard { background: var(--card-sky); backdrop-filter: blur(22px) saturate(1.2); -webkit-backdrop-filter: blur(22px) saturate(1.2); box-shadow: var(--card-sky-edge); color: #fff; }
.lskycard :is(p, h6, small) { color: var(--card-sky-ink-2); }
.lcard { border-radius: 16px; background: var(--card, var(--raised)); box-shadow: var(--chip-edge); color: var(--ink); }

/* LumaUI: Mini cards (owning-app parity)
   When an app shows something another app owns, it shows that app's own card: a person (Contacts), an event (Calendar),
   a song (Tide), a place (Maps). Files use the file card. Same size family as the file card. */
.lmini { display: flex; align-items: center; gap: 11px; width: 300px; max-width: 100%; min-height: 60px; padding: 8px 10px 8px 8px; border-radius: 16px; background: var(--chip); box-shadow: var(--chip-edge); color: var(--ink); text-align: left; }
.lmini > span:not(.lmth) { flex: 1; min-width: 0; display: grid; gap: 2px; } .lmini b { font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lmini small { font: var(--t-caption); letter-spacing: .01em; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.lmini .bt.sm { height: 28px; padding: 0 12px; flex: none; border-radius: 9px; background: var(--fill-2); font-size: 12px; font-weight: 600; } .lmini .bt.sm:hover { background: var(--fill-3); }
.lmth { position: relative; width: 44px; height: 44px; flex: none; display: grid; place-items: center; }
.lmini.person { flex-wrap: wrap; width: 320px; padding: 12px; } .lmini.person .lcacts { flex: 1 0 100%; margin-top: 4px; }
.lmini .onluma { display: inline-flex; align-items: center; gap: 5px; } .lmini .onluma i { width: 6px; height: 6px; border-radius: 50%; corner-shape: round; background: var(--good); }
.lmini.event .lmth { width: 44px; border-radius: 10px; align-content: center; gap: 0; background: oklch(0.36 0.07 var(--eh) / .75); box-shadow: inset 3px 0 0 oklch(0.72 0.13 var(--eh)); }
