.calnarrow .calbar .seg button:nth-child(4) { display: flex; }
.calnarrow .cflow { padding-top: 74px; } .calnarrow .cday:first-child .cdh > b, .calnarrow .cday.today .cdh > b { }
   /* the older narrow rule hid Month; on a phone it is the view */
