.pev .px small { display: flex; align-items: center; gap: 5px; font-size: 12.5px; color: var(--ink-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } .pev .px small svg.i { width: 13px; height: 13px; flex: none; }
.pday h6 { margin: 20px 4px 8px; font-size: 12.5px; font-weight: 600; color: var(--ink-3); letter-spacing: .01em; }
