.cweek.c3 .cwh, .cweek.c3 .cwb { grid-template-columns: 44px repeat(3, minmax(0, 1fr)); }
.calnarrow .calbar { width: auto; gap: 4px; } .calnarrow .calbar .ctoday { flex: none; padding: 0 14px; }
.calnarrow .calbar.calcomp { width: calc(100% - 24px); } .calnarrow .calbar.calcomp .cadd { flex: 1; min-width: 0; } .calnarrow .calbar.calcomp input { font-size: 16px; }

/* the photo viewer's title sits below the action row on a phone, not beside it */
html[data-phone] .win.phone .viewer .vt { top: 110px !important; left: 20px !important; right: 20px; }

/* ── Stage and Canvas, narrow ── */
.ststrip { position: absolute; left: 0; right: 0; z-index: 5; }
.ststrip .stsh { display: flex; align-items: baseline; gap: 8px; width: 100%; padding: 0 18px 10px; text-align: left; } .ststrip .stsh svg.i { width: 16px; height: 16px; margin-left: auto; align-self: center; color: var(--ink-3); } .ststrip .stsh b { font-size: 17px; font-weight: 700; } .ststrip .stsh span { font-size: 13px; color: var(--ink-3); }
.ststrip .strow { display: flex; gap: 10px; overflow-x: auto; scrollbar-width: none; padding: 4px 16px 8px; scroll-snap-type: x proximity; }
.ststrip .stth { position: relative; flex: none; display: block; width: auto; scroll-snap-align: center; border-radius: 10px; padding: 0; } .ststrip .stth .stmini { display: block; overflow: hidden; border-radius: 9px; box-shadow: 0 0 0 1px var(--hair); }
.ststrip .stth.on .stmini { box-shadow: 0 0 0 2.5px oklch(0.7 0.14 var(--acc)); } .ststrip .stth em { position: absolute; left: 6px; bottom: 5px; font-style: normal; font-size: 10.5px; font-weight: 700; color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,.6); }
