.ststrip .stpn { margin: 14px 16px 0; padding: 14px 16px; border-radius: 16px; background: var(--fill-1); } .ststrip .stpn b { display: flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--ink-3); } .ststrip .stpn b svg.i { width: 14px; height: 14px; } .ststrip .stpn p { margin: 6px 0 0; font-size: 15px; line-height: 1.45; }
@container win (max-width: 559px) { #st-left, #st-notes, #st-right.min { display: none !important; } }   /* the strip holds the slides and notes */

/* ── Session, narrow: tracks as an icon column, as mobile music apps do, so the arrangement gets the width.
   The song's name moves up into the top row as a context chip. ── */
@container win (max-width: 559px) {
  .sewin .searr { grid-template-columns: 62px minmax(0, 1fr) !important; }
  .sewin .sehead { grid-template-columns: 4px 1fr !important; grid-template-rows: auto auto; row-gap: 2px; column-gap: 0 !important; padding: 0 4px 0 0 !important; justify-items: center; }
  .sewin .sehead > .sestrip { grid-row: 1 / span 2; align-self: stretch; }
  .sewin .sehead > .seic { grid-column: 2; }
  .sewin .sehead > .sename { grid-column: 2; display: block !important; max-width: 54px; text-align: center; } .sewin .sehead > .sename b { display: block; font-size: 10px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } .sewin .sehead > .sename small { display: none; }
  .sewin .sehead > :nth-child(n+4):not(.sename) { display: none !important; }
  .sewin .sehh { visibility: hidden; }
}
html[data-phone] #w-session.phone .sectx { position: absolute; left: 12px; top: 50px; z-index: 46; height: 44px; display: flex; flex-direction: column; justify-content: center; padding: 0 14px; border-radius: 16px; background: var(--bar); box-shadow: var(--bar-edge); -webkit-backdrop-filter: blur(24px); backdrop-filter: blur(24px); }
html[data-phone] #w-session.phone .sectx b { font-size: 13.5px; font-weight: 650; } html[data-phone] #w-session.phone .sectx span { font-size: 11.5px; color: var(--ink-3); }
.win:not(.phone) .sectx { display: none; }

/* ── Photos' view island, top right ── */
.pview { position: absolute; right: 16px; top: 16px; z-index: 12; display: flex; align-items: center; gap: 8px; padding: 4px; }
.pview[hidden] { display: none; } .pview .psize { display: flex; align-items: center; gap: 6px; padding: 0 8px 0 4px; } .pview .psize input { width: 90px; } .pview .psize svg.i { width: 15px; height: 15px; color: var(--ink-3); }
@container win (max-width: 720px) { .pview .psize { display: none; } }
html[data-phone] .win.phone .pview { right: 12px; top: 4px; padding: 3px; border-radius: 16px; } html[data-phone] .win.phone .pview .seg { height: 38px; } html[data-phone] .win.phone .pview .seg button { height: 32px; padding: 0 10px; font-size: 13px; }

/* ── The phone action bar, one shape family ────────────────────────────────────────────────────────
   Every control in the bar is the same 48px button with the same 20px corner. A switch inside the bar is not a
   second frame: it is a run of those buttons, the chosen one raised. Collapsed search is one of those buttons too. */
html[data-phone] .win.phone .fbar:not(.phtabs) > .seg { height: 48px; padding: 0; gap: 2px; background: none !important; box-shadow: none !important; border-radius: 0; }
html[data-phone] .win.phone .fbar:not(.phtabs) > .seg > .ind { display: none !important; }
html[data-phone] .win.phone .fbar:not(.phtabs) > .seg > button { height: 48px; min-width: 48px; border-radius: 20px; }
html[data-phone] .win.phone .fbar:not(.phtabs) > .seg > button.on { background: var(--chip); box-shadow: var(--chip-edge); color: var(--ink); }
html[data-phone] .win.phone .fbar:not(.phsearch) > label.srch:not(.tphq):not(.dppq):not(.keep) { width: 48px !important; min-width: 48px; height: 48px; padding: 0 !important; justify-content: center; border-radius: 20px; background: none; box-shadow: none; }
html[data-phone] .win.phone .fbar:not(.phsearch) > label.srch:not(.tphq):not(.dppq):not(.keep) > svg.i { width: 20px; height: 20px; }
html[data-phone] .win.phone .fbar:not(.phsearch) > label.srch:not(.tphq):not(.dppq):not(.keep) > :not(svg) { display: none; }
/* the window's frame margin goes on a phone: the app is the screen */
html[data-phone] .win.phone > .ibody { padding: 0 !important; gap: 0 !important; }
html[data-phone] .win.phone .tpane.isle, html[data-phone] .win.phone #tm-panes { inset: 0 !important; left: 0 !important; right: 0 !important; margin: 0 !important; border-radius: 0 !important; }

/* ── Phone, narrow: the list page ── */
.pnwin.pnlistview .pnside { display: flex !important; position: absolute; inset: 0; z-index: 20; width: auto; padding: 56px 12px 110px; background: var(--win); }
.pnwin.pnlistview #pn-main { position: absolute; inset: 0; z-index: 21; background: none !important; box-shadow: none !important; pointer-events: none; } .pnwin.pnlistview #pn-main > * { visibility: hidden; } .pnwin.pnlistview #pn-main > .fbar { visibility: visible; pointer-events: auto; }
.pnwin.pnlistview .pnside::before { display: block; padding: 0 6px 10px; font-size: 32px; font-weight: 750; letter-spacing: -.03em; color: var(--ink); }
.pnwin.pnlistview[data-pnview="recents"] .pnside::before { content: "Recents"; } .pnwin.pnlistview[data-pnview="contacts"] .pnside::before { content: "Contacts"; } .pnwin.pnlistview[data-pnview="vm"] .pnside::before { content: "Voicemail"; }
.pnwin.pnlistview .pnside::before { order: -2; }
.pnwin.pnlistview .pnside .pnlist .pnrow { min-height: 64px; } .pnwin.pnlistview .pnside .pnfoot { order: -1; margin-bottom: 8px; } .pnwin.pnlistview .pnside .pnq { height: 44px; border-radius: 16px; } .pnwin.pnlistview .pnside .pnq input { font-size: 16px; }
.pnwin.pnlistview .pnside .pnfavs { order: -1; } .pnwin.pnlistview .pnrow.on { background: none; box-shadow: none; }
.pnlback { position: absolute; left: 12px; top: 50px; z-index: 30; display: flex; align-items: center; gap: 2px; height: 44px; padding: 0 14px 0 8px; border-radius: 16px; font-size: 14px; font-weight: 600; }
.pnlback svg.i { width: 20px; height: 20px; }
html[data-phone] .pnwin.phone:has(.pnlback) .pnbody { padding-top: 100px; }

/* ── Charlie, narrow: a mail thread as a phone reads one ──────────────────────────────────────────
   Top row: back and the thread's actions. Below it, the subject as the page title (who's in it underneath).
   Messages run the full width: the sender's avatar sits small beside their name, not in a column of its own.
   The reply bar is one line: reply-to-all as an icon, then the field, then attach. */
@container win (max-width: 559px) {
  .crwin .crhead { position: relative; flex-wrap: wrap; padding: 0 16px 6px !important; pointer-events: auto; }
  html[data-phone] .crwin.phone .crhead { margin-top: calc(50px - var(--phsafe, 100px)); }   /* the actions share the back button's row */
  .crwin .crhead > .crright { order: 1; margin-left: auto; }
  .crwin .crhead > .crsubj { order: 2; flex-basis: 100%; height: auto; margin-top: 14px; padding: 0; background: none !important; box-shadow: none !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; text-align: left; gap: 10px; }
  .crwin .crhead > .crsubj b { font-size: 22px; font-weight: 700; letter-spacing: -.02em; line-height: 1.2; white-space: normal !important; overflow: visible; max-width: none !important; }
  .crwin .crhead > .crsubj small { font-size: 13px; } .crwin .crhead > .crsubj > svg.i { display: none; }
  .crwin .crhead > .crsubj .crstk { display: none; }
  #cr-main:has(> .crhead) { display: flex; flex-direction: column; } #cr-main > .scroll { flex: 1; min-height: 0; }
  .crwin .crpad { padding: 6px 14px 150px !important; }
  .crwin .crmsg { display: block; margin: 18px 0; }
  .crwin .crmsg .crcol { display: grid; grid-template-columns: 26px minmax(0, 1fr); column-gap: 8px; row-gap: 6px; max-width: none !important; width: 100%; justify-items: stretch !important; }
  .crwin .crmsg .crwho { display: none; }
  .crwin .crmsg .crmeta { grid-column: 2; align-self: center; padding-left: 0 !important; margin-left: 0 !important; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .crwin .crmsg .crmeta::before { content: ""; }
  .crwin .crmsg .crcol > :not(.crmeta, .crmav) { grid-column: 1 / -1; }
  .crwin .crmsg.out .crcol > .crbub { margin-left: 36px; } .crwin .crmsg.in .crcol > .crbub { margin-right: 20px; }
  .crwin .crmsg .crfiles { display: grid; gap: 6px; } .crwin .crmsg .crfiles .lfc { width: 100%; }
  .crwin .crmsg .crmav { display: block; grid-column: 1; grid-row: 1; width: 26px; height: 26px; }
