  --pg-run: oklch(0.8 0.1 var(--acc)); --pg-run-soft: oklch(0.72 0.12 var(--acc) / .15); --pg-red: oklch(0.72 0.16 25); --pg-red-soft: oklch(0.66 0.17 25 / .15);
