  --pg-amber: oklch(0.56 0.14 65); --pg-amber-soft: oklch(0.75 0.14 75 / .16); --pg-violet: oklch(0.5 0.14 300); --pg-violet-soft: oklch(0.65 0.13 300 / .13);
  --pg-run: oklch(0.5 0.13 var(--acc)); --pg-run-soft: oklch(0.6 0.12 var(--acc) / .12); --pg-red: oklch(0.55 0.19 25); --pg-red-soft: oklch(0.6 0.17 25 / .1);
