#pg-top .pgproj .pgpm { width: 20px; height: 20px; } #pg-top .pgproj em { font-style: normal; font-weight: 500; font-size: 12.5px; color: var(--ink-3); } #pg-top .pgproj > svg.i { width: 15px; height: 15px; color: var(--ink-3); }
#pg-top .pgdiv { width: 1px; height: 18px; background: var(--hair); margin: 0 2px 0 4px; }
#pg-top .pgtbr { margin-left: auto; display: flex; align-items: center; gap: 4px; margin-right: -6px; }
.pgtb { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px 0 9px; border-radius: 10px; font-size: 12.5px; font-weight: 550; color: var(--ink-2); } .pgtb:hover, .pgtb.on { background: var(--fill-1); color: var(--ink); } .pgtb svg.i { width: 16px; height: 16px; }
.pgtb .stat { width: 6px; height: 6px; } .pgtb .pgmini { width: 26px; height: 4px; border-radius: 2px; background: var(--fill-2); overflow: hidden; } .pgtb .pgmini i { display: block; height: 100%; background: var(--ink-2); border-radius: 2px; }
.pghere { display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 10px 0 5px; border-radius: 10px; font-size: 12.5px; font-weight: 550; color: var(--ink-2); } .pghere:hover { background: var(--fill-1); color: var(--ink); }
.pgstk { display: inline-flex; } .pgstk > * + * { margin-left: -6px; } .pgstk .av { box-shadow: 0 0 0 2px var(--win); }
.pgpres { position: relative; display: inline-flex; } .pgpres::after { content: ""; position: absolute; right: -1px; bottom: -1px; width: 7px; height: 7px; border-radius: 50%; background: var(--good); box-shadow: 0 0 0 2px var(--win); corner-shape: round; }
