/* ── The rail: projects, and the goals of the one you're in ── */
.pgwin .pgside { width: 244px; padding-bottom: 10px; }
.pgside .sh:first-child { margin-top: 6px; }
.pgprow { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; padding: 6px 8px; border-radius: 12px; text-align: left; } .pgprow:hover { background: var(--fill-1); }
.pgprow > span { flex: 1; min-width: 0; display: grid; } .pgprow b { font-size: 13.5px; font-weight: 650; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } .pgprow small { font-size: 11.5px; color: var(--ink-3); letter-spacing: .01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pgprow.on { cursor: default; } .pgprow.on:hover { background: none; }
.pgprow .ib { width: 28px; height: 28px; border-radius: 9px; color: var(--ink-3); } .pgprow .ib svg.i { width: 16px; height: 16px; }
.pggoals { position: relative; display: grid; gap: 1px; margin: 2px 0 4px 0; }
.pggl { position: relative; display: flex; align-items: center; gap: 10px; width: 100%; min-height: 46px; padding: 6px 10px 6px 10px; border-radius: 12px; text-align: left; color: var(--ink-2); transition: background .12s; }
.pggl:hover { background: var(--fill-1); } .pggl.on { color: var(--ink); background: var(--chip); box-shadow: var(--chip-edge); }
[data-mode="light"] .pgwin .pggl.on { background: var(--fill-2); box-shadow: none; }
.pggl > span { flex: 1; min-width: 0; display: grid; line-height: 1.25; } .pggl b { font-weight: 550; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } .pggl.on b { font-weight: 600; }
.pggl small { font-size: 11.5px; color: var(--ink-3); letter-spacing: .01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pggl small.needs { color: var(--pg-amber); } .pggl small.rvw { color: var(--pg-violet); } .pggl small.work { color: var(--pg-run); } .pggl small.live { color: var(--good); }
.pggl .av { flex: none; }
.pggl.chat { min-height: 40px; } .pggl.add { min-height: 36px; color: var(--ink-3); } .pggl.add:hover { color: var(--ink); } .pggl.add svg.i { width: 16px; height: 16px; margin: 0 1px; }
/* the state glyph: one shape per state, so it reads without colour */
.pgg { position: relative; flex: none; width: 18px; height: 18px; display: grid; place-items: center; }
