.pgg.chat::before { display: none; } .pgg img { width: 18px; height: 18px; border-radius: 6px; box-shadow: 0 1px 2px rgba(0,0,0,.25); }
@keyframes pgspin { to { transform: rotate(360deg); } }
.pgside .pgfoot { flex: none; display: grid; gap: 2px; margin-top: 6px; padding-top: 8px; box-shadow: inset 0 1px 0 var(--hair); }
.pgside .pgfoot .si { height: 36px; } .pgside .pgfoot .si em { margin-left: auto; }
