.pghd .pgmeta > span { display: inline-flex; align-items: center; gap: 6px; } .pghd .pgmeta > i.d { width: 3px; height: 3px; border-radius: 50%; background: var(--ink-4); corner-shape: round; }
.pghdr { display: flex; align-items: flex-start; gap: 12px; } .pghdr > div { flex: 1; min-width: 0; display: grid; gap: 6px; } .pghdr .ib { width: 32px; height: 32px; margin-top: -2px; color: var(--ink-3); }
.pgpill { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: 8px; font-size: 11.5px; font-weight: 650; letter-spacing: .01em; white-space: nowrap; }
.pgpill.needs { color: var(--pg-amber); background: var(--pg-amber-soft); } .pgpill.work { color: var(--pg-run); background: var(--pg-run-soft); } .pgpill.rvw { color: var(--pg-violet); background: var(--pg-violet-soft); }
.pgpill.live { color: var(--good); background: color-mix(in oklab, var(--good) 14%, transparent); } .pgpill.paused, .pgpill.draft { color: var(--ink-3); background: var(--fill-1); } .pgpill.chat { display: none; }
.pgpill .pgspin { width: 9px; height: 9px; }
.pgspin { display: inline-block; width: 11px; height: 11px; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: pgspin .8s linear infinite; flex: none; corner-shape: round; }
.pgday { justify-self: center; margin: 6px 0 -2px; font-size: 11.5px; font-weight: 600; color: var(--ink-3); letter-spacing: .02em; }
/* your words, theirs, and the agent's */
.pgme { display: grid; justify-items: end; gap: 4px; }
.pgme p { margin: 0; max-width: min(78%, 560px); padding: 9px 15px 10px; border-radius: 20px 20px 6px 20px; font-size: 14px; line-height: 1.5; color: #fff; background: linear-gradient(180deg, oklch(0.52 0.12 var(--acc)), oklch(0.46 0.12 var(--acc))); box-shadow: inset 0 1px 0 oklch(1 0 0 / .18), 0 0 0 1px rgba(0,0,0,.35), 0 1px 2px rgba(0,0,0,.3); }
[data-mode="light"] .pgme p { background: linear-gradient(180deg, oklch(0.6 0.13 var(--acc)), oklch(0.54 0.13 var(--acc))); box-shadow: inset 0 1px 0 oklch(1 0 0 / .25), 0 0 0 1px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.12); }
.pgme p .pgpt { display: inline-flex; align-items: center; gap: 5px; margin: 0 4px 0 0; padding: 1px 7px 1px 5px; border-radius: 7px; background: rgba(255,255,255,.18); font-size: 12px; font-weight: 600; vertical-align: 1px; } .pgme p .pgpt svg.i { width: 12px; height: 12px; }
.pgme small, .pgthem small { font-size: 11px; color: var(--ink-3); letter-spacing: .01em; padding: 0 6px; }
.pgthem { display: grid; grid-template-columns: 28px minmax(0, 1fr); column-gap: 8px; align-items: end; } .pgthem > .av { grid-row: 1 / span 2; align-self: end; margin-bottom: 18px; }
.pgthem p { justify-self: start; margin: 0; max-width: min(84%, 560px); padding: 9px 15px 10px; border-radius: 20px 20px 20px 6px; font-size: 14px; line-height: 1.5; background: var(--chip); box-shadow: var(--chip-edge); }
.pgthem small { grid-column: 2; }
.pgsay { justify-self: start; max-width: min(90%, 640px); padding: 10px 15px 10px; border-radius: 20px 20px 20px 6px; background: var(--chip); box-shadow: var(--chip-edge); }
.pgsay > p { margin: 0 0 8px; font-size: 14px; line-height: 1.55; } .pgsay > p:last-of-type { margin-bottom: 0; }
.pgsay .pgchips { margin-top: 10px; }
.pgfoot2 { display: flex; align-items: center; gap: 7px; margin-top: 9px; padding-top: 7px; box-shadow: inset 0 1px 0 var(--hair); font-size: 11.5px; color: var(--ink-3); letter-spacing: .01em; white-space: nowrap; }
.pgfoot2 .pgam { width: 16px; height: 16px; font-size: 8.5px; } .pgfoot2 > span { display: inline-flex; align-items: center; gap: 5px; } .pgfoot2 > span + span::before { content: "·"; margin-right: 7px; color: var(--ink-4); } .pgfoot2 svg.i { width: 13px; height: 13px; }
.pgthink { justify-self: start; display: inline-flex; align-items: center; gap: 10px; padding: 10px 15px; border-radius: 20px 20px 20px 6px; background: var(--chip); box-shadow: var(--chip-edge); font-size: 13.5px; color: var(--ink-3); }
.pgdots { display: inline-flex; gap: 4px; } .pgdots i { width: 6px; height: 6px; border-radius: 50%; background: var(--ink-3); animation: pgdot 1.2s ease-in-out infinite; corner-shape: round; } .pgdots i:nth-child(2) { animation-delay: .15s; } .pgdots i:nth-child(3) { animation-delay: .3s; }
@keyframes pgdot { 0%, 60%, 100% { opacity: .3; transform: none; } 30% { opacity: 1; transform: translateY(-2px); } }
.pgchips { display: flex; flex-wrap: wrap; gap: 6px; }
.pgchip { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px 0 10px; border-radius: 11px; font-size: 12.5px; font-weight: 600; background: var(--fill-1); color: var(--ink); } .pgchip:hover { background: var(--fill-2); } .pgchip svg.i { width: 15px; height: 15px; color: var(--ink-3); }
.pgchip .pgg { width: 14px; height: 14px; }
.pgnote { display: flex; align-items: center; gap: 8px; justify-self: center; max-width: 100%; padding: 6px 12px; border-radius: 10px; font-size: 12px; color: var(--ink-3); letter-spacing: .01em; text-align: center; } .pgnote svg.i { width: 14px; height: 14px; flex: none; } .pgnote b { color: var(--ink-2); font-weight: 600; }

/* ── Cards: the agent's vocabulary. One shape: a kind line, a title, the body, actions at the foot ── */
.pgc { position: relative; border-radius: 18px; background: var(--pg-card); box-shadow: var(--pg-card-edge); overflow: hidden; }
.pgfresh { animation: pgin .38s var(--ease) both; }
@keyframes pgin { from { opacity: 0; transform: translateY(6px); } }
.pgch { display: flex; align-items: center; gap: 8px; padding: 12px 16px 0; min-height: 34px; }
.pgk { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 650; color: var(--ink-3); letter-spacing: .02em; } .pgk svg.i { width: 14px; height: 14px; }
.pgk.needs { color: var(--pg-amber); } .pgk.rvw { color: var(--pg-violet); } .pgk.work { color: var(--pg-run); } .pgk.live, .pgk.good { color: var(--good); }
.pgch time, .pgch .pgr { margin-left: auto; font-size: 11.5px; color: var(--ink-3); letter-spacing: .01em; font-variant-numeric: tabular-nums; white-space: nowrap; }
.pgct { margin: 0; padding: 4px 16px 0; font-size: 15.5px; font-weight: 650; letter-spacing: -.012em; line-height: 1.35; }
.pgcb { padding: 10px 16px 14px; font-size: 13.5px; line-height: 1.5; color: var(--ink-2); } .pgcb > p { margin: 0 0 8px; } .pgcb > p:last-child { margin-bottom: 0; }
.pgcf { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 10px 12px 12px 16px; box-shadow: inset 0 1px 0 var(--hair); } .pgcf .bt { height: 34px; border-radius: 11px; } .pgcf .bt.sm { height: 30px; border-radius: 10px; }
.pgcf .pgsub { font-size: 12px; color: var(--ink-3); letter-spacing: .01em; } .pgcf .pgsub b { color: var(--ink-2); font-weight: 600; }
.pgcf.flat { box-shadow: none; padding-top: 0; }
/* Brief and Recipe: facts as rows */
.pgkv { display: grid; gap: 0; margin: 0; } .pgkv > div { display: grid; grid-template-columns: 112px minmax(0, 1fr); gap: 12px; padding: 9px 0; box-shadow: inset 0 -1px 0 var(--hair); } .pgkv > div:last-child { box-shadow: none; padding-bottom: 2px; }
.pgkv dt { font-size: 12.5px; color: var(--ink-3); letter-spacing: .01em; padding-top: 1px; } .pgkv dd { margin: 0; font-size: 13.5px; color: var(--ink); line-height: 1.5; }
.pgkv dd small { display: block; margin-top: 2px; font-size: 12.5px; color: var(--ink-3); line-height: 1.45; }
.pgkv [contenteditable="true"] { outline: none; border-radius: 6px; box-shadow: 0 0 0 1.5px var(--acc-ink); padding: 0 4px; margin: 0 -4px; }
.pgrec { display: grid; gap: 2px; } .pgrecr { display: grid; grid-template-columns: 32px minmax(0, 1fr); gap: 12px; padding: 8px 0; align-items: start; } .pgrecr + .pgrecr { box-shadow: inset 0 1px 0 var(--hair); }
.pgrecr > i { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; background: var(--fill-1); color: var(--ink-2); } .pgrecr > i svg.i { width: 16px; height: 16px; }
.pgrecr b { display: block; font-size: 13.5px; font-weight: 600; color: var(--ink); } .pgrecr b em { font-style: normal; font-weight: 500; color: var(--ink-3); } .pgrecr span { display: block; font-size: 12.5px; color: var(--ink-3); line-height: 1.45; margin-top: 1px; }
.pgmore { margin-top: 10px; padding: 12px 14px; border-radius: 14px; background: var(--well); box-shadow: var(--well-edge); font-size: 13px; color: var(--ink-2); line-height: 1.55; } .pgmore p { margin: 0 0 6px; } .pgmore p:last-child { margin: 0; }
/* Plan: stories, each with checks a person can see */
.pgstories { display: grid; gap: 12px; counter-reset: st; }
.pgstory { display: grid; grid-template-columns: 24px minmax(0, 1fr); gap: 4px 10px; }
.pgstory > i { grid-row: 1 / span 2; width: 22px; height: 22px; border-radius: 8px; display: grid; place-items: center; background: var(--fill-1); font-style: normal; font-size: 11.5px; font-weight: 700; color: var(--ink-2); margin-top: 1px; }
.pgstory > b { font-size: 13.5px; font-weight: 600; color: var(--ink); line-height: 1.4; }
.pgchecks { display: grid; gap: 3px; } .pgck { display: flex; align-items: flex-start; gap: 8px; font-size: 12.5px; color: var(--ink-2); line-height: 1.45; }
.pgck > svg.i { width: 14px; height: 14px; margin-top: 2px; color: var(--ink-4); }
.pgest { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; margin-top: 14px; border-radius: 14px; overflow: hidden; background: var(--hair); box-shadow: 0 0 0 1px var(--hair); }
.pgest > div { display: grid; gap: 1px; padding: 9px 12px; background: var(--pg-card); } .pgest small { font-size: 11.5px; color: var(--ink-3); letter-spacing: .01em; } .pgest b { font-size: 13px; font-weight: 600; color: var(--ink); }
.pgagreed { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: var(--good); } .pgagreed svg.i { width: 14px; height: 14px; }
/* Step: live progress, folding to one line */
.pgstep .pgnow { display: flex; align-items: center; gap: 10px; padding: 4px 16px 0; font-size: 13.5px; color: var(--ink); font-weight: 550; }
.pgstep .pgnow .pgspin { color: var(--pg-run); }
.pgbar { position: relative; height: 4px; margin: 12px 16px 0; border-radius: 2px; background: var(--fill-1); overflow: hidden; } .pgbar i { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 2px; background: linear-gradient(90deg, oklch(0.62 0.13 var(--acc)), oklch(0.74 0.12 var(--acc))); transition: width .6s var(--ease); }
.pgbar.indef i { width: 30%; animation: pgslide 1.6s ease-in-out infinite; } @keyframes pgslide { from { left: -30%; } to { left: 100%; } }
.pgstats { display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 10px 16px 12px; font-size: 12px; color: var(--ink-3); letter-spacing: .01em; } .pgstats span { display: inline-flex; align-items: center; gap: 6px; font-variant-numeric: tabular-nums; } .pgstats b { color: var(--ink-2); font-weight: 600; } .pgstats svg.i { width: 13px; height: 13px; }
.pgstats button { display: inline-flex; align-items: center; gap: 5px; color: var(--ink-2); font-weight: 600; } .pgstats button:hover { color: var(--ink); }
.pgfiles { margin: 0 16px 12px; padding: 4px; border-radius: 12px; background: var(--well); box-shadow: var(--well-edge); display: grid; }
.pgfile { display: flex; align-items: center; gap: 8px; height: 30px; padding: 0 8px; border-radius: 8px; font-family: var(--pg-mono); font-size: 11.5px; color: var(--ink-2); text-align: left; } button.pgfile:hover { background: var(--fill-1); color: var(--ink); }
.pgfile svg.i { width: 13px; height: 13px; color: var(--ink-3); } .pgfile em { margin-left: auto; font-style: normal; font-family: var(--font); font-size: 11px; } .pgfile em ins { text-decoration: none; color: var(--pg-add); } .pgfile em del { text-decoration: none; color: var(--pg-del); margin-left: 6px; }
.pgsubs { display: grid; gap: 2px; padding: 8px 16px 0; } .pgsubs > span { display: flex; align-items: center; gap: 9px; font-size: 12.5px; color: var(--ink-3); } .pgsubs > span svg.i { width: 14px; height: 14px; } .pgsubs > span.sdone { color: var(--ink-2); } .pgsubs > span.sdone svg.i { color: var(--good); } .pgsubs > span.snow { color: var(--ink); font-weight: 550; } .pgsubs > span .pgspin { width: 12px; height: 12px; margin: 0 1px; color: var(--pg-run); }
.pgsubs > span.snext::before { content: ""; width: 10px; height: 10px; margin: 0 2px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ink-4); corner-shape: round; }
.pgfold { display: flex; align-items: center; gap: 10px; min-height: 48px; padding: 0 8px 0 14px; }
