.pgfold > b { flex: 1; min-width: 0; font-size: 13.5px; font-weight: 550; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } .pgfold > small { font-size: 12px; color: var(--ink-3); white-space: nowrap; font-variant-numeric: tabular-nums; letter-spacing: .01em; }
.pgfold .ib { width: 30px; height: 30px; border-radius: 9px; color: var(--ink-3); } .pgfold .ib svg.i { width: 15px; height: 15px; }
.pgfoldx { box-shadow: inset 0 1px 0 var(--hair); }
/* Decision: only you can decide */
