.pgopts { display: grid; gap: 6px; margin-top: 2px; }
.pgopt { position: relative; display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 2px 12px; padding: 11px 14px 12px 12px; border-radius: 14px; text-align: left; background: var(--pg-row); box-shadow: inset 0 0 0 1px var(--hair); transition: background .12s, box-shadow .12s; }
.pgopt:hover { background: var(--fill-1); } .pgopt > i { grid-row: 1 / span 2; width: 18px; height: 18px; margin-top: 1px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ink-3); corner-shape: round; transition: box-shadow .15s; }
.pgopt.on { background: var(--fill-1); box-shadow: inset 0 0 0 1.5px var(--ink-2); } .pgopt.on > i { box-shadow: inset 0 0 0 5.5px var(--ink); }
.pgopt b { font-size: 13.5px; font-weight: 600; color: var(--ink); display: flex; flex-wrap: wrap; align-items: center; gap: 8px; } .pgopt span { font-size: 12.5px; color: var(--ink-3); line-height: 1.45; }
.pgrecm { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 7px; border-radius: 6px; font-size: 11px; font-weight: 650; letter-spacing: .01em; color: var(--ink-2); background: var(--fill-2); } .pgrecm svg.i { width: 11px; height: 11px; }
.pgopt.picked { cursor: default; } .pgopt.dim { opacity: .45; cursor: default; } .pgopt.dim:hover, .pgopt.picked:hover { background: var(--pg-row); }
.pgopt.picked { background: var(--fill-1); box-shadow: inset 0 0 0 1.5px var(--good); } .pgopt.picked > i { box-shadow: none; background: var(--good); display: grid; place-items: center; } .pgopt.picked > i::after { content: ""; width: 8px; height: 4px; margin-top: -2px; border: solid #fff; border-width: 0 0 2px 2px; transform: rotate(-45deg); }
.pgdef { margin: 10px 2px 0; font-size: 12px; color: var(--ink-3); letter-spacing: .01em; line-height: 1.45; }
/* Proof: what the checker saw */
