.pgshot { position: relative; width: 150px; height: 312px; flex: none; border-radius: 22px; overflow: hidden; background: #111; box-shadow: 0 0 0 1px rgba(0,0,0,.4), 0 8px 18px -8px rgba(0,0,0,.5); cursor: zoom-in; }
