.pgshot .pgplay { position: absolute; inset: 0; display: grid; place-items: center; z-index: 2; } .pgshot .pgplay b { width: 46px; height: 46px; border-radius: 50%; display: grid; place-items: center; background: rgba(20,20,22,.62); color: #fff; backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); box-shadow: 0 0 0 1px rgba(255,255,255,.18); corner-shape: round; }
