.pgshot .pghl { position: absolute; z-index: 3; border-radius: 10px; box-shadow: 0 0 0 2px oklch(0.78 0.15 75), 0 0 0 999px rgba(0,0,0,.35); animation: pgin .3s var(--ease); pointer-events: none; }
.pgpchecks { display: grid; gap: 2px; align-content: start; }
.pgpck { display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; gap: 10px; align-items: start; padding: 7px 8px 7px 6px; border-radius: 10px; text-align: left; font-size: 13px; line-height: 1.45; color: var(--ink); } button.pgpck:hover { background: var(--fill-1); }
.pgpck > em { font-style: normal; font-size: 11.5px; color: var(--ink-3); white-space: nowrap; padding-top: 1px; } button.pgpck:hover > em { color: var(--ink); }
.pgst { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; margin-top: 1px; corner-shape: round; } .pgst svg.i { width: 11px; height: 11px; stroke-width: 3; }
.pgst.pass { background: var(--good); color: #fff; } .pgst.fail { background: var(--pg-red); color: #fff; } .pgst.wait { box-shadow: inset 0 0 0 1.5px var(--ink-4); } .pgst.run { color: var(--pg-run); } .pgst.run .pgspin { width: 13px; height: 13px; }
.pgby { display: flex; align-items: center; gap: 7px; margin: 8px 8px 0 6px; font-size: 11.5px; color: var(--ink-3); letter-spacing: .01em; line-height: 1.4; } .pgby svg.i { width: 13px; height: 13px; flex: none; }
@container pgmain (max-width: 520px) { .pgproof { grid-template-columns: minmax(0, 1fr); } .pgshot { justify-self: center; } }
/* Heads-up: changed something nobody asked for */
