.pgheads > i { width: 30px; height: 30px; flex: none; border-radius: 10px; display: grid; place-items: center; background: var(--pg-amber-soft); color: var(--pg-amber); } .pgheads > i svg.i { width: 16px; height: 16px; }
.pgheads > div { flex: 1; min-width: 0; display: grid; gap: 2px; } .pgheads b { font-size: 13px; font-weight: 600; } .pgheads p { margin: 0; font-size: 13px; color: var(--ink-2); line-height: 1.5; }
.pgheads .bt { flex: none; } .pgheads.undone p { text-decoration: line-through; text-decoration-color: var(--ink-4); color: var(--ink-3); } .pgheads.undone > i { background: var(--fill-1); color: var(--ink-3); }
/* Review card */
.pgrv { display: grid; gap: 8px; padding: 10px 16px 4px; } .pgrvr { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--ink-2); } .pgrvr svg.i { width: 16px; height: 16px; color: var(--ink-3); } .pgrvr b { color: var(--ink); font-weight: 600; } .pgrvr .pgst { margin: 0; }
