.pgpr { position: relative; display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 2px 12px; align-items: center; width: 100%; padding: 9px 10px; border-radius: 13px; text-align: left; } button.pgpr:hover { background: var(--fill-1); } .pgpr.on { background: var(--chip); box-shadow: var(--chip-edge); }
