.pgempty { display: grid; justify-items: center; gap: 8px; max-width: 260px; text-align: center; color: var(--ink-3); font-size: 13px; line-height: 1.5; } .pgempty > i { width: 64px; height: 64px; border-radius: 20px; display: grid; place-items: center; background: var(--fill-1); box-shadow: inset 0 0 0 1px var(--hair); color: var(--ink-3); } .pgempty > i svg.i { width: 26px; height: 26px; } .pgempty b { color: var(--ink-2); font-size: 14px; font-weight: 600; }
