.pgbrow { flex: none; height: 52px; display: flex; align-items: center; gap: 12px; padding: 0 18px; background: #ecebea; border-bottom: 1px solid #d9d6d2; }
.pgbrow > i { width: 12px; height: 12px; border-radius: 50%; background: #d4d1cd; corner-shape: round; } .pgbrow > span { flex: 0 1 520px; margin: 0 auto; height: 32px; border-radius: 9px; background: #fff; display: flex; align-items: center; justify-content: center; gap: 8px; font: 500 14px var(--font); color: #57534e; } .pgbrow > span svg.i { width: 14px; height: 14px; }
