/* ── Kiln: Maya's pottery studio, in its own warm style (deliberately not Luma) ── */
.kl { --kc: #f7f1e8; --kc2: #efe5d6; --kink: #2b211a; --kink2: #6b5a4b; --kink3: #9a8877; --kclay: #b5532f; --kclay2: #9c4224; --ksage: #5f6f52; --kline: #e4d8c7; --kcard: #fffaf3;
  position: absolute; inset: 0; display: flex; flex-direction: column; background: var(--kc); color: var(--kink); font: 15px/1.45 'Atkinson Hyperlegible', system-ui, sans-serif; letter-spacing: 0; overflow: hidden; text-align: left; }
.kl * { box-sizing: border-box; } .kl button { font: inherit; color: inherit; }
.kl h1, .kl h2, .kl h3 { font-family: Newsreader, Georgia, serif; font-weight: 500; letter-spacing: -.01em; margin: 0; }
