.klhd { display: flex; align-items: center; gap: 9px; padding: 10px 20px 6px; } .klhd b { font: 600 21px Newsreader, Georgia, serif; letter-spacing: -.01em; } .klhd .klsp { flex: 1; }
.klmk { width: 30px; height: 30px; flex: none; } .klmk svg { width: 100%; height: 100%; display: block; }
