.klsign i { width: 16px; height: 16px; border-radius: 5px; background: linear-gradient(160deg, #6aa0ff, #3f7ed6); }
.klhero { padding: 14px 20px 6px; } .klhero small { display: block; font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--kclay); } .klhero h1 { margin-top: 6px; font-size: 32px; line-height: 1.08; } .klhero p { margin: 8px 0 0; color: var(--kink2); font-size: 15px; }
.klph { display: flex; gap: 8px; padding: 14px 20px 4px; overflow-x: auto; scrollbar-width: none; } .klph > i { flex: none; width: 150px; height: 112px; border-radius: 14px; overflow: hidden; display: block; box-shadow: 0 1px 2px rgba(60,30,10,.15); } .klph > i svg { width: 100%; height: 100%; display: block; }
.klh2 { display: flex; align-items: baseline; justify-content: space-between; padding: 18px 20px 8px; } .klh2 h2 { font-size: 22px; } .klh2 span { font-size: 13px; color: var(--kink3); }
