.klc { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 4px 12px; padding: 12px; border-radius: 18px; background: var(--kcard); box-shadow: 0 0 0 1px var(--kline), 0 1px 2px rgba(60,30,10,.06); }
.kld { grid-row: 1 / span 2; width: 52px; height: 56px; border-radius: 12px; display: grid; align-content: center; justify-items: center; background: var(--kc2); line-height: 1.05; } .kld small { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; color: var(--kclay); } .kld b { font: 500 23px Newsreader, Georgia, serif; }
.klc h3 { font-size: 18px; line-height: 1.2; align-self: end; } .klc p { margin: 0; font-size: 13px; color: var(--kink2); }
.klc .klact { grid-column: 1 / -1; display: flex; align-items: center; gap: 10px; margin-top: 8px; } .klspots { font-size: 12.5px; font-weight: 700; color: var(--ksage); } .klspots.full { color: var(--kclay2); } .klspots.few { color: #a0601a; }
.klbtn { margin-left: auto; height: 38px; padding: 0 16px; border-radius: 19px; background: var(--kink); color: #fff8ee !important; font-size: 14px; font-weight: 700; display: inline-flex; align-items: center; gap: 6px; } .klbtn.alt { background: transparent; color: var(--kclay2) !important; box-shadow: inset 0 0 0 1.5px var(--kclay); } .klbtn.off { background: var(--kc2); color: var(--kink3) !important; cursor: default; }
