.klsheet { position: absolute; left: 0; right: 0; bottom: 0; z-index: 4; padding: 10px 20px 34px; border-radius: 26px 26px 0 0; background: var(--kcard); box-shadow: 0 -10px 40px rgba(60,30,10,.25); animation: klup .35s cubic-bezier(.3,1.1,.4,1) both; } @keyframes klup { from { transform: translateY(40%); opacity: 0; } }
