.pgnew > .pgpm { margin-bottom: 18px; }
.pgnewmark { width: 60px; height: 60px; border-radius: 18px; box-shadow: 0 14px 30px -12px rgba(0,0,0,.55); }
.pgnew h1 { margin: 18px 0 6px; font-size: 30px; font-weight: 700; letter-spacing: -.025em; } .pgnew > p { margin: 0 0 22px; font-size: 14px; line-height: 1.55; color: var(--ink-3); max-width: 480px; }
.pgbig { display: grid; gap: 10px; padding: 8px; border-radius: 22px; background: var(--well); box-shadow: var(--well-edge); }
.pgbig textarea { width: 100%; min-height: 92px; padding: 10px 12px 4px; border: 0; outline: 0; resize: none; background: none; color: var(--ink); font: 500 18px/1.45 var(--font); letter-spacing: -.01em; } .pgbig textarea::placeholder { color: var(--ink-4); }
.pgbig > div { display: flex; align-items: center; gap: 6px; } .pgbig .ib { width: 40px; height: 40px; border-radius: 13px; } .pgbig .bt.key { height: 40px; border-radius: 13px; padding: 0 16px; }
