.pgex .pgarr { opacity: 0; transition: opacity .15s; } .pgex:hover .pgarr { opacity: 1; }

/* ── Pages that take the room: the Project book, the code, the review ── */
.pgpg { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.pgpgh { flex: none; display: flex; align-items: center; gap: 10px; height: 52px; padding: 0 12px 0 10px; box-shadow: inset 0 -1px 0 var(--hair); }
.pgpgh .bt { height: 34px; border-radius: 11px; } .pgpgh > b { font-size: 14px; font-weight: 650; } .pgpgh > small { font-size: 12.5px; color: var(--ink-3); }
.pgpgh .pgback { padding: 0 12px 0 6px; gap: 4px; color: var(--ink-2); } .pgpgh .pgback:hover { color: var(--ink); }
.pgpgb { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--fill-3) transparent; }
/* the book */
.pgbook { display: grid; grid-template-columns: 200px minmax(0, 1fr); gap: 36px; max-width: 1080px; margin: 0 auto; padding: 30px 40px 120px; }
.pgtoc { position: sticky; top: 24px; align-self: start; display: grid; gap: 1px; } .pgtoc > b { margin: 0 10px 10px; font-size: 11.5px; font-weight: 650; color: var(--ink-3); letter-spacing: .02em; }
.pgtoc button { height: 32px; padding: 0 10px; border-radius: 9px; text-align: left; font-size: 13px; color: var(--ink-2); display: flex; align-items: center; gap: 10px; } .pgtoc button:hover { background: var(--fill-1); color: var(--ink); } .pgtoc button.on { background: var(--fill-1); color: var(--ink); font-weight: 600; } .pgtoc button svg.i { width: 15px; height: 15px; color: var(--ink-3); }
.pgdoc { min-width: 0; max-width: 760px; } .pgdoch { display: flex; align-items: center; gap: 16px; margin-bottom: 8px; } .pgdoch h1 { margin: 0; font-size: 34px; font-weight: 700; letter-spacing: -.03em; line-height: 1.1; } .pgdoch p { margin: 4px 0 0; font-size: 14px; color: var(--ink-3); }
