.pgsec { padding-top: 34px; scroll-margin-top: 10px; } .pgsec > h2 { display: flex; align-items: center; gap: 10px; margin: 0 0 4px; font-size: 20px; font-weight: 700; letter-spacing: -.02em; } .pgsec > h2 .bt { margin-left: auto; } .pgsec > h2 + p { margin: 0 0 14px; font-size: 13.5px; color: var(--ink-3); line-height: 1.5; }
.pgsec > h2 .pgk { margin-left: 2px; }
.pgbox { border-radius: 18px; background: var(--pg-card); box-shadow: var(--pg-card-edge); padding: 6px 18px; } .pgbox + .pgbox { margin-top: 10px; }
.pgnnl { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.pgcol { display: grid; align-content: start; gap: 6px; padding: 10px; border-radius: 18px; background: var(--well); box-shadow: var(--well-edge); min-height: 120px; } .pgcol > h3 { display: flex; align-items: center; gap: 8px; margin: 2px 4px 4px; font-size: 12.5px; font-weight: 650; color: var(--ink-2); } .pgcol > h3 em { font-style: normal; font-weight: 500; color: var(--ink-3); margin-left: auto; } .pgcol > p { margin: 4px 6px; font-size: 12px; color: var(--ink-3); }
.pgtile { display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 2px 8px; padding: 9px 10px; border-radius: 12px; text-align: left; background: var(--pg-card); box-shadow: var(--pg-card-edge); } button.pgtile:hover { filter: brightness(1.04); }
.pgtile > .pgg { grid-row: 1 / span 2; margin-top: 1px; } .pgtile b { font-size: 13px; font-weight: 600; line-height: 1.3; } .pgtile small { font-size: 11.5px; color: var(--ink-3); display: flex; align-items: center; gap: 6px; } .pgtile small .av { flex: none; }
.pgrows { display: grid; } .pgrow { display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 2px 12px; align-items: center; padding: 11px 0; box-shadow: inset 0 -1px 0 var(--hair); } .pgrow:last-child { box-shadow: none; }
.pgrow > i { grid-row: 1 / span 2; width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center; background: var(--fill-1); color: var(--ink-2); font-style: normal; } .pgrow > i svg.i { width: 17px; height: 17px; } .pgrow > i.av { background-color: transparent; }
.pgrow > .av { grid-row: 1 / span 2; } .pgrow > .pgam, .pgrow > .pgpm { grid-row: 1 / span 2; }
.pgrow > b { font-size: 13.5px; font-weight: 600; min-width: 0; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; } .pgrow > small { grid-column: 2; font-size: 12.5px; color: var(--ink-3); line-height: 1.45; letter-spacing: .005em; }
.pgrow > .pgend { grid-row: 1 / span 2; grid-column: 3; display: flex; align-items: center; gap: 6px; } .pgrow > .pgend > em { font-style: normal; font-size: 12px; color: var(--ink-3); white-space: nowrap; font-variant-numeric: tabular-nums; }
.pgrow.dim > b, .pgrow.dim > small { opacity: .5; }
.pgtag { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 7px; border-radius: 6px; font-size: 11px; font-weight: 650; letter-spacing: .01em; color: var(--ink-2); background: var(--fill-1); white-space: nowrap; } .pgtag svg.i { width: 11px; height: 11px; }
.pgtag.good { color: var(--good); background: color-mix(in oklab, var(--good) 13%, transparent); } .pgtag.amber { color: var(--pg-amber); background: var(--pg-amber-soft); } .pgtag.violet { color: var(--pg-violet); background: var(--pg-violet-soft); } .pgtag.run { color: var(--pg-run); background: var(--pg-run-soft); } .pgtag.red { color: var(--pg-red); background: var(--pg-red-soft); }
.pgjour { display: grid; gap: 12px; } .pgjr { padding: 14px 16px 16px; border-radius: 18px; background: var(--pg-card); box-shadow: var(--pg-card-edge); } .pgjr > b { display: block; margin-bottom: 12px; font-size: 13.5px; font-weight: 600; } .pgjr > b em { font-style: normal; font-weight: 500; color: var(--ink-3); }
.pgjn { display: flex; align-items: stretch; gap: 0; overflow-x: auto; scrollbar-width: none; padding-bottom: 2px; }
.pgjn > span { flex: 1 0 118px; display: grid; gap: 3px; align-content: start; padding: 10px 12px; border-radius: 13px; background: var(--well); box-shadow: var(--well-edge); } .pgjn > span small { font-size: 10.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--ink-3); } .pgjn > span b { font-size: 12.5px; font-weight: 600; } .pgjn > span em { font-style: normal; font-size: 11.5px; color: var(--ink-3); font-family: var(--pg-mono); }
.pgjn > i { flex: 0 0 26px; display: grid; place-items: center; color: var(--ink-4); } .pgjn > i svg.i { width: 15px; height: 15px; }
.pgjn > span.new { box-shadow: var(--well-edge), inset 0 0 0 1.5px oklch(0.72 0.12 300 / .55); }
.pgfilt { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 10px; } .pgfilt button { height: 30px; padding: 0 12px; border-radius: 10px; font-size: 12.5px; font-weight: 600; color: var(--ink-2); box-shadow: inset 0 0 0 1px var(--hair); } .pgfilt button:hover { background: var(--fill-1); } .pgfilt button.on { background: var(--chip); box-shadow: var(--chip-edge); color: var(--ink); }
.pgstats2 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; } .pgstats2 > div { display: grid; gap: 2px; padding: 14px 16px; border-radius: 16px; background: var(--pg-card); box-shadow: var(--pg-card-edge); } .pgstats2 small { font-size: 12px; color: var(--ink-3); } .pgstats2 b { font-size: 22px; font-weight: 650; letter-spacing: -.02em; font-variant-numeric: tabular-nums; } .pgstats2 em { font-style: normal; font-size: 12px; color: var(--ink-3); }
.pgcodebtn { display: flex; align-items: center; gap: 14px; width: 100%; padding: 16px 18px; border-radius: 18px; text-align: left; background: var(--pg-term); color: oklch(0.9 0.005 265); box-shadow: 0 0 0 1px rgba(0,0,0,.3); } .pgcodebtn:hover { filter: brightness(1.15); } .pgcodebtn > span { flex: 1; display: grid; gap: 2px; } .pgcodebtn b { font-size: 14px; font-weight: 600; } .pgcodebtn small { font: 12px var(--pg-mono); color: oklch(0.7 0.01 265); } .pgcodebtn svg.i { width: 20px; height: 20px; }
@container win (max-width: 1060px) { .pgbook { grid-template-columns: minmax(0, 1fr); padding: 26px 28px 120px; } .pgtoc { display: none; } .pgnnl { grid-template-columns: minmax(0, 1fr); } .pgstats2 { grid-template-columns: 1fr 1fr; } }
/* code, one step down */
.pgcode { flex: 1; min-height: 0; display: grid; grid-template-columns: 240px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; }
.pgfiles2 { grid-row: 1 / span 2; overflow-y: auto; padding: 10px 8px; box-shadow: inset -1px 0 0 var(--hair); scrollbar-width: none; } .pgfiles2 h6 { margin: 8px 10px 6px; font-size: 11.5px; font-weight: 650; color: var(--ink-3); letter-spacing: .01em; }
.pgfr { display: flex; align-items: center; gap: 8px; width: 100%; height: 30px; padding: 0 8px; border-radius: 8px; text-align: left; font-family: var(--pg-mono); font-size: 12px; color: var(--ink-2); white-space: nowrap; } .pgfr:hover { background: var(--fill-1); color: var(--ink); } .pgfr.on { background: var(--fill-2); color: var(--ink); }
.pgfr svg.i { width: 14px; height: 14px; color: var(--ink-3); flex: none; } .pgfr span { overflow: hidden; text-overflow: ellipsis; } .pgfr em { margin-left: auto; font-style: normal; font-family: var(--font); font-size: 10.5px; font-weight: 700; color: var(--pg-amber); } .pgfr em.a { color: var(--pg-add); }
.pgsrc { overflow: auto; min-width: 0; font: 12.5px/1.65 var(--pg-mono); background: var(--isle); }
