/* ══ YouTube (v73, 21 Oct 2026): the picture is the room ══════════════════════════════════════
   A YouTube client in the kit. Browsing is a gallery lit by what's featured; watching is one
   object (picture and transport, Reel's rule) with the video's own light spilling round it
   (--yh, the video's hue). The sidebar holds places and the people you follow; the floating
   bar holds what you do: search while browsing, and the video's actions while watching. A
   video playing behind you rides in the bar (it grows a mini player) so you never lose it.
   Window widths: wide (two columns while watching), medium (one column), narrow (the phone). */
.ytwin { --yh: 25; }
.ytwin .ibody { padding-left: 0; }
.ytside { width: 232px; flex: none; display: flex; flex-direction: column; padding: 0 10px 10px; transition: width .28s var(--ease), padding .28s var(--ease), opacity .2s; }
.ytside .scr { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; } .ytside .sh:first-child { margin-top: 4px; }
.ytside .si em { font-style: normal; font-size: 11.5px; color: var(--ink-4); font-variant-numeric: tabular-nums; }
.ytside .si .yav { width: 22px; height: 22px; margin: 0 -2px; }
.ytside .si .ytlv { margin-left: auto; padding: 1px 6px; border-radius: 5px; background: oklch(0.6 0.2 25); color: #fff; font-size: 10px; font-weight: 700; letter-spacing: .04em; }
.ytside .si .ytnew { margin-left: auto; width: 7px; height: 7px; border-radius: 50%; background: var(--acc-ink); }
#w-youtube.lsideoff .ytside { width: 0; padding: 0; opacity: 0; overflow: hidden; } #w-youtube.lsideoff .ibody { padding-left: 8px; }
.ytwin .ibody { padding-left: 0; }
.ytmain { position: relative; isolation: isolate; container-type: inline-size; container-name: ytm; }
.ytmain > .scroll { position: absolute; inset: 0; overflow-y: auto; scrollbar-width: none; }
/* the light of what's on show */
.ytwash { position: absolute; inset: 0 0 auto 0; height: 520px; z-index: -1; pointer-events: none; background: radial-gradient(90% 100% at 30% 0%, oklch(0.42 0.1 var(--yh) / .42), transparent 70%); transition: background .6s var(--ease); }
[data-mode="light"] .ytwash { background: radial-gradient(90% 100% at 30% 0%, oklch(0.9 0.06 var(--yh) / .8), transparent 70%); }
.yav { display: block; flex: none; border-radius: 50%; background: center/cover no-repeat var(--fill-2); }
.yav.logo { background-size: 64%; background-color: #111; }

/* ── Browsing ── */
.ytpage { padding: 20px 28px 120px; max-width: 1600px; margin: 0 auto; }
.ytpage h1 { margin: 6px 0 18px; font-size: 26px; font-weight: 700; letter-spacing: -.025em; }
.ythero { position: relative; width: 100%; display: flex; align-items: flex-end; height: 340px; border-radius: 18px; overflow: hidden; background: #000; box-shadow: 0 30px 60px -32px oklch(0.2 0.08 var(--yh) / .9), 0 0 0 1px rgba(255,255,255,.04); text-align: left; color: #fff; }
.ythero img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform 1.2s var(--ease); }
.ythero:hover img { transform: scale(1.02); }
.ythero::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(6,7,9,.86), rgba(6,7,9,.45) 45%, transparent 75%), linear-gradient(0deg, rgba(6,7,9,.55), transparent 40%); }
.ythero .tx { position: relative; z-index: 1; max-width: 560px; padding: 0 32px 30px; }
.ythero .by { display: flex; align-items: center; gap: 9px; font-size: 13px; font-weight: 600; color: rgba(255,255,255,.85); }
.ythero .by .yav { width: 26px; height: 26px; }
.ythero h2 { margin: 12px 0 0; font-size: 34px; font-weight: 700; letter-spacing: -.035em; line-height: 1.06; text-wrap: balance; }
.ythero .mt { margin-top: 8px; font-size: 13.5px; color: rgba(255,255,255,.7); }
.ythero .pr { display: flex; align-items: center; gap: 12px; margin-top: 16px; font-size: 12.5px; color: rgba(255,255,255,.75); font-variant-numeric: tabular-nums; } .ythero .pr .lprog { width: 220px; background: rgba(255,255,255,.18); box-shadow: none; }
.ythero .acts { display: flex; gap: 8px; margin-top: 18px; }
.ythero .acts .bt { height: 36px; border-radius: 12px; padding: 0 15px 0 13px; font-weight: 600; }
.ythero .acts .bt:not(.pri) { background: rgba(255,255,255,.16); color: #fff; box-shadow: inset 0 1px 0 rgba(255,255,255,.14); backdrop-filter: blur(12px); }
.ythero .acts .bt svg.i { width: 16px; height: 16px; }
.ytchips { display: flex; gap: 6px; margin: 26px 0 22px; overflow-x: auto; scrollbar-width: none; }
.ytchips button { flex: none; height: 32px; padding: 0 13px; border-radius: 10px; background: var(--fill-1); color: var(--ink-2); font-size: 13px; font-weight: 550; }
.ytchips button:hover { background: var(--fill-2); color: var(--ink); }
.ytchips button.on { background: var(--key); color: var(--key-ink); box-shadow: var(--key-edge); }
.ytsec { display: flex; align-items: baseline; gap: 10px; margin: 30px 0 14px; } .ytsec b { font-size: 17px; font-weight: 700; letter-spacing: -.015em; } .ytsec span { font-size: 12.5px; color: var(--ink-3); }
.ytsec .ytmore { margin-left: auto; font-size: 12.5px; font-weight: 600; color: var(--acc-ink); }
.ytgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(268px, 1fr)); gap: 30px 18px; }
.ytcard { display: grid; gap: 12px; text-align: left; min-width: 0; }
.ytth { position: relative; display: block; aspect-ratio: 16 / 9; border-radius: 12px; overflow: hidden; background: #111; box-shadow: 0 0 0 1px rgba(255,255,255,.04); }
.ytth img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .5s var(--ease); }
.ytcard:hover .ytth img { transform: scale(1.045); }
.ytth .dur { position: absolute; right: 8px; bottom: 8px; padding: 2px 6px; border-radius: 6px; background: rgba(0,0,0,.74); color: #fff; font-style: normal; font-size: 11.5px; font-weight: 650; font-variant-numeric: tabular-nums; letter-spacing: .01em; }
.ytth .dur.live, .ytlive { display: inline-flex; align-items: center; gap: 5px; background: oklch(0.58 0.21 25); color: #fff; font-weight: 750; letter-spacing: .05em; }
.ytth .dur.live::before, .ytlive::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: #fff; }
.ytlive { padding: 2px 7px; border-radius: 6px; font-size: 11px; font-style: normal; }
.ytth .pg { position: absolute; left: 0; right: 0; bottom: 0; height: 4px; background: rgba(255,255,255,.22); } .ytth .pg i { display: block; height: 100%; background: var(--prog); }
.ytth .hov { position: absolute; top: 8px; right: 8px; display: flex; flex-direction: column; gap: 6px; opacity: 0; transform: translateX(6px); transition: opacity .18s, transform .22s var(--ease); }
.ytcard:hover .ytth .hov, .ytcard:focus-within .ytth .hov { opacity: 1; transform: none; }
.ytth .hov button { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; background: rgba(12,13,16,.72); color: #fff; backdrop-filter: blur(10px); }
.ytth .hov button:hover { background: rgba(12,13,16,.9); } .ytth .hov button.on { color: oklch(0.82 0.12 var(--acc)); } .ytth .hov svg.i { width: 15px; height: 15px; }
.ytth .skim { position: absolute; left: 0; bottom: 0; height: 3px; width: 0; background: #fff; opacity: .9; }
.ytcard:hover .ytth .skim { animation: ytskim 6s linear forwards; }
@keyframes ytskim { to { width: 100%; } }
.ytmeta { display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 0 12px; }
.ytmeta > button { align-self: start; display: block; width: 34px; height: 34px; padding: 0; }
.ytmeta .yav { width: 34px; height: 34px; }
.ytmeta b { display: block; white-space: nowrap; text-overflow: ellipsis; overflow: hidden; font-size: 14.5px; font-weight: 650; line-height: 34px; margin: -8px 0 -6px; letter-spacing: -.01em; color: var(--ink); }
.ytmeta > span { min-width: 0; } .ytmeta > span > span { display: block; margin-top: 4px; font-size: 12.5px; color: var(--ink-3); line-height: 1.4; letter-spacing: .01em; }
.ytmeta span button { color: inherit; font-size: inherit; } .ytmeta span button:hover { color: var(--ink); }
.ytver { display: inline-block; width: 13px; height: 13px; margin-left: 3px; vertical-align: -2px; color: var(--ink-3); } .ytver svg.i { width: 13px; height: 13px; }
/* shorts */
.ytshorts { display: grid; grid-auto-flow: column; grid-auto-columns: 172px; gap: 14px; overflow-x: auto; scrollbar-width: none; padding-bottom: 4px; }
.ytshort { position: relative; aspect-ratio: 9 / 16; border-radius: 14px; overflow: hidden; background: #111; text-align: left; color: #fff; }
.ytshort img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s var(--ease); } .ytshort:hover img { transform: scale(1.04); }
.ytshort::after { content: ""; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,.72), transparent 46%); }
.ytshort b { position: absolute; left: 12px; right: 12px; bottom: 30px; z-index: 1; font-size: 13.5px; font-weight: 650; line-height: 1.25; text-wrap: balance; }
.ytshort span { position: absolute; left: 12px; bottom: 11px; z-index: 1; font-size: 11.5px; color: rgba(255,255,255,.78); }
/* subscriptions: the people first */
.ytppl { display: flex; gap: 18px; overflow-x: auto; scrollbar-width: none; padding: 4px 2px 6px; }
.ytppl button { position: relative; flex: none; display: grid; justify-items: center; gap: 7px; width: 72px; font-size: 12px; font-weight: 550; color: var(--ink-2); }
.ytppl .yav { width: 60px; height: 60px; box-shadow: 0 0 0 2px var(--isle), 0 0 0 4px transparent; transition: box-shadow .2s; }
.ytppl button.new .yav { box-shadow: 0 0 0 2.5px var(--isle), 0 0 0 4.5px oklch(0.7 0.14 var(--acc)); }
.ytppl button.live .yav { box-shadow: 0 0 0 2.5px var(--isle), 0 0 0 4.5px oklch(0.6 0.21 25); }
.ytppl button span { max-width: 72px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ytppl .ytlive { position: absolute; top: 48px; padding: 0 5px; font-size: 9.5px; box-shadow: 0 0 0 2px var(--isle); }
/* lists: history, search, up next */
.ytrows { display: grid; gap: 4px; }
.ytrow { display: grid; grid-template-columns: 248px minmax(0, 1fr) auto; gap: 18px; align-items: start; padding: 8px; margin: 0 -8px; border-radius: 16px; text-align: left; }
.ytrow:hover { background: var(--fill-1); }
.ytrow .ytth { border-radius: 10px; }
.ytrow .tx b { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; font-size: 15.5px; font-weight: 650; line-height: 1.32; letter-spacing: -.01em; }
.ytrow .tx .by { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: 12.5px; color: var(--ink-2); } .ytrow .tx .by .yav { width: 22px; height: 22px; }
.ytrow .tx span.s { display: block; margin-top: 6px; font-size: 12.5px; color: var(--ink-3); letter-spacing: .01em; }
.ytrow .tx p { margin: 8px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--ink-3); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ytrow .ychav { width: 88px; height: 88px; }
.ytrow > .ib { opacity: 0; } .ytrow:hover > .ib { opacity: 1; }
.ytday { margin: 26px 0 10px; font-size: 13px; font-weight: 650; color: var(--ink-2); } .ytday:first-child { margin-top: 4px; }
.ythist { display: flex; align-items: center; gap: 12px; margin: 0 0 18px; } .ythist .srch { width: 340px; } .ythist .sp { flex: 1; }
.ythist .hpause { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--ink-2); }
/* a playlist: the cover holds the subject's actions; the list is the playlist */
.ytpl { display: grid; grid-template-columns: 340px minmax(0, 1fr); gap: 28px; align-items: start; }
.ytplc { position: sticky; top: 64px; padding: 20px; border-radius: 20px; overflow: hidden; isolation: isolate; color: #fff; background: #111; }
.ytplc::before { content: ""; position: absolute; inset: -40px; z-index: -2; background: var(--pi) center/cover; filter: blur(40px) saturate(1.5) brightness(.55); }
.ytplc::after { content: ""; position: absolute; inset: 0; z-index: -1; background: linear-gradient(180deg, transparent, rgba(0,0,0,.45)); }
.ytplc .ytth { border-radius: 12px; box-shadow: 0 20px 40px -18px rgba(0,0,0,.8); }
.ytplc h2 { margin: 18px 0 4px; font-size: 26px; font-weight: 700; letter-spacing: -.03em; }
.ytplc .mt { font-size: 13px; color: rgba(255,255,255,.72); }
.ytplc .acts { display: flex; gap: 8px; margin-top: 18px; }
.ytplc .acts .bt { flex: 1; justify-content: center; height: 36px; border-radius: 12px; font-weight: 600; }
.ytplc .acts .bt:not(.pri) { background: rgba(255,255,255,.16); color: #fff; box-shadow: inset 0 1px 0 rgba(255,255,255,.14); }
.ytplc .acts .ib { color: #fff; background: rgba(255,255,255,.16); border-radius: 12px; }
.ytpll .ytrow { grid-template-columns: 22px 168px minmax(0, 1fr) auto; align-items: center; }
.ytpll .ytrow .n { font-size: 12.5px; color: var(--ink-4); text-align: center; font-variant-numeric: tabular-nums; }
.ytpll .ytrow .tx b { font-size: 14px; }
/* a channel */
.ytbanner { position: relative; height: 210px; border-radius: 18px; overflow: hidden; background: #111; }
.ytbanner img { width: 100%; height: 100%; object-fit: cover; }
.ytbanner::after { content: ""; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,.35), transparent 60%); }
.ytchead { display: flex; align-items: center; gap: 22px; margin: 22px 0 6px; }
.ytchead .yav { width: 104px; height: 104px; box-shadow: 0 16px 36px -16px rgba(0,0,0,.7); }
.ytchead h2 { margin: 0; font-size: 30px; font-weight: 750; letter-spacing: -.035em; } .ytchead .mt { margin-top: 4px; font-size: 13px; color: var(--ink-3); }
.ytchead p { margin: 8px 0 0; max-width: 560px; font-size: 13.5px; line-height: 1.5; color: var(--ink-2); }
.ytchead .sp { flex: 1; }
.ytctabs { margin: 18px 0 22px; }

/* ── Watching ── */
.ytwatch { display: grid; grid-template-columns: minmax(0, 1fr) 360px; grid-template-rows: auto 1fr; gap: 0 28px; padding: 20px 28px 120px; max-width: 1640px; margin: 0 auto; }
.ytwatch > .ytpw { grid-column: 1; grid-row: 1; }
.ytwatch > .ytinfo { grid-column: 1; grid-row: 2; }
.ytwatch > .ytnext { grid-column: 2; grid-row: 1 / span 2; }
.ytwatch.theater > .ytpw { grid-column: 1 / -1; }
.ytwatch.theater > .ytnext { grid-row: 2; }
.ytpw { position: relative; isolation: isolate; }
.ytamb { position: absolute; inset: -6% -4%; z-index: -1; background: var(--pi) center/cover; filter: blur(64px) saturate(1.8); opacity: .55; transform: scale(1.05); pointer-events: none; transition: opacity .6s; }
[data-mode="light"] .ytamb { opacity: .38; }
.ytwin.ytplaying .ytamb { animation: ytbreathe 7s ease-in-out infinite alternate; }
