.ytscrub:hover .ytprev { opacity: 1; }
.ytprev i { display: block; aspect-ratio: 16 / 9; border-radius: 8px; background-size: 260%; }
.ytprev b { display: block; margin-top: 5px; font-size: 12px; font-weight: 650; } .ytprev span { font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
