.ytctl .selcd b { font-size: 15px; } .ytctl .selcd small { max-width: 130px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.yttr { display: flex; align-items: center; gap: 2px; } .yttr .seplay { margin: 0 6px; }
.ytctl .ib { width: 36px; height: 36px; border-radius: 12px; }
.ytctl .ib.on { color: var(--acc-ink); }
.ytctr { justify-self: end; display: flex; align-items: center; gap: 2px; }
