.ytvol { display: flex; align-items: center; } .ytvol input.rng { width: 0; opacity: 0; transition: width .25s var(--ease), opacity .2s; } .ytvol:hover input.rng, .ytvol:focus-within input.rng { width: 80px; opacity: 1; margin-right: 6px; }
/* under the picture */
