.ytchaps i { display: block; aspect-ratio: 16 / 9; border-radius: 8px; background-size: 320%; }
.ytchaps b { font-size: 12.5px; font-weight: 650; color: var(--ink); } .ytchaps span { font-size: 11.5px; color: var(--acc-ink); font-variant-numeric: tabular-nums; font-weight: 600; }
