html:is([data-form="tablet"], [data-form="fold"]) .win.phone .ttl > div:not(.fviews) { min-width: 0; }
html:is([data-form="tablet"], [data-form="fold"]) .win.phone .ttl .fviews .seg { height: 44px; padding: 3px; border-radius: 15px; } html:is([data-form="tablet"], [data-form="fold"]) .win.phone .ttl .fviews .seg button { height: 38px; min-width: 44px; border-radius: 12px; }
